/* HTML5プロフェッショナル認定試験 レベル1(Ver2.5)の問題。公式の出題範囲 https://html5exam.jp/outline/objectives_lv1.html の主題1.1〜1.5に合わせた単元。
   c=選択肢、k=正解の番号(0始まり)。code=記述問題の模範解答(別解も正解になり得ます) */
var HTML5_L1 = [
{"id": "l1a", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "Webの基礎知識(HTTP・HTMLの書式・Web技術)(1/2)", "dm": 1.5, "ps": [{"t": "ステータスコード404", "q": "HTTPのステータスコード404が表すものはどれか。", "c": ["サーバの内部でエラーが起きた", "リクエストされたリソースが見つからない", "リクエストが成功した", "リソースが恒久的に別のURLへ移動した"], "k": 1, "e": "404は Not Found で、リソースが見つからないことを表します。成功は200、恒久的な移動は301、サーバ内部のエラーは500です。"}, {"t": "リダイレクト", "q": "リソースが恒久的に別のURLへ移動したことを表すステータスコードはどれか。", "c": ["301", "200", "403", "304"], "k": 0, "e": "301は Moved Permanently(恒久的な移動)です。200は成功(OK)、304は Not Modified(更新されていないので、キャッシュを使える)、403は Forbidden(アクセスが禁止されている)です。"}, {"t": "ステータスコードの分類", "q": "HTTPのステータスコードで、5xx(500番台)が表すものはどれか。", "c": ["成功", "クライアントエラー", "情報", "サーバエラー"], "k": 3, "e": "1xxは情報、2xxは成功、3xxはリダイレクト、4xxはクライアントエラー、5xxはサーバエラーです。"}, {"t": "HEADメソッド", "q": "HTTPのHEADメソッドの説明として適切なものはどれか。", "c": ["フォームのデータをリクエストのボディに入れて送る", "サーバのリソースを削除する", "通信を暗号化してから送る", "GETと同じ内容を要求するが、レスポンスにはボディが含まれず、ヘッダだけが返る"], "k": 3, "e": "HEADは、GETと同じ内容を要求しますが、レスポンスはヘッダだけで、ボディは返りません。更新日時やサイズの確認に使えます。削除はDELETE、ボディでデータを送るのは主にPOSTです。"}, {"t": "GETとPOST", "q": "HTTPのGETメソッドについて、適切なものはどれか。", "c": ["送るデータは、必ず暗号化される", "レスポンスにボディを含まない", "ファイルのアップロードに最も適している", "送るデータは、URLのクエリ文字列(?の後ろ)に付けて送られる"], "k": 3, "e": "GETでは、データがURLのクエリ文字列に付きます。URLは履歴などに残るので、パスワードなどを送るのには向きません。暗号化するのはHTTPS(SSL/TLS)で、GETとは関係ありません。ファイルの送信には、普通はPOSTを使います。"}, {"t": "HTTPS", "q": "HTTPSの説明として適切なものはどれか。", "c": ["ファイルを転送するためのプロトコルで、既定のポート番号は21", "HTTPの通信を圧縮したもので、既定のポート番号は80", "HTTPの通信をSSL/TLSで暗号化したもので、既定のポート番号は443", "メールを送るためのプロトコルで、既定のポート番号は25"], "k": 2, "e": "HTTPSは、SSL/TLSで暗号化したHTTPで、既定のポート番号は443です。HTTPは80、SMTP(メールの送信)は25、FTP(ファイル転送)は21です。"}, {"t": "Cookie", "q": "サーバが、ブラウザにCookieを保存させるときに使う、HTTPのレスポンスヘッダはどれか。", "c": ["Cache-Control", "Set-Cookie", "Cookie", "Authorization"], "k": 1, "e": "サーバは、レスポンスの Set-Cookie ヘッダでCookieを送ります。ブラウザは、それ以降のリクエストで Cookie ヘッダに付けて送り返します。Cache-Controlはキャッシュの制御、Authorizationは認証の情報を送るヘッダです。"}, {"t": "Basic認証", "q": "HTTPのBasic認証について、適切なものはどれか。", "c": ["パスワードを送らずに、指紋で認証する", "ユーザー名とパスワードをBase64でエンコードして送るだけなので、HTTPSと組み合わせて使うのが望ましい", "パスワードを必ず暗号化して送るので、HTTPでも安全である", "Cookieが使えないブラウザでは使えない"], "k": 1, "e": "Basic認証は、「ユーザー名:パスワード」をBase64でエンコードして送ります。Base64は暗号化ではなく、すぐに元に戻せるので、HTTPSと組み合わせます。"}, {"t": "文書型宣言", "q": "HTML5の文書型宣言(DOCTYPE)として正しいものはどれか。", "c": ["<!DOCTYPE html>", "<?xml version=\"1.0\"?>", "<!DOCTYPE HTML5>", "<html doctype=\"5\">"], "k": 0, "e": "HTML5の文書型宣言は <!DOCTYPE html> です。大文字・小文字は区別しないので、<!doctype html> とも書けます。文書の先頭に書きます。"}, {"t": "文字参照", "q": "HTMLで「&lt;」と書いたとき、ブラウザに表示される文字はどれか。", "c": [">", "空白(ノーブレークスペース)", "<", "&"], "k": 2, "e": "&lt; は「<」(less than)を表す文字参照です。「>」は &gt;、「&」は &amp;、ノーブレークスペースは &nbsp; です。タグと区別するために使います。"}, {"t": "文字コードと言語", "q": "言語が日本語、文字コードがUTF-8、タイトルが「会社案内」のHTML文書の、html要素の開始タグからhead要素の終了タグまでを記述しなさい。", "code": "<html lang=\"ja\">\n<head>\n  <meta charset=\"UTF-8\">\n  <title>会社案内</title>\n</head>", "e": "言語は html要素の lang属性、文字コードは meta要素の charset属性で指定します。charset は「utf-8」と小文字で書いても正解です。meta charset は、head の中のなるべく前に書きます。", "m": 3}, {"t": "クロスサイト・スクリプティング", "q": "利用者が入力したスクリプトが、そのままWebページに出力され、そのページを見た人のブラウザで実行されてしまう攻撃はどれか。", "c": ["クロスサイト・リクエスト・フォージェリ(CSRF)", "ディレクトリ・トラバーサル", "クロスサイト・スクリプティング(XSS)", "SQLインジェクション"], "k": 2, "e": "XSSは、入力されたスクリプトを、ページに出力するときにエスケープしないことで起きます。SQLインジェクションは、不正なSQL文を実行させる攻撃です。ディレクトリ・トラバーサルは、「../」などで公開していないファイルにアクセスする攻撃です。CSRFは、ログイン中の利用者に、意図しない操作のリクエストを送らせる攻撃です。"}, {"t": "ディレクトリ・トラバーサル", "q": "ファイル名を指定するパラメータに「../」などを入れて、公開していないファイルを読み出す攻撃はどれか。", "c": ["ディレクトリ・トラバーサル", "クロスサイト・スクリプティング", "HTTPヘッダ・インジェクション", "SQLインジェクション"], "k": 0, "e": "上位のディレクトリへの移動を表す「../」を使って、本来は見えないファイルにアクセスする攻撃が、ディレクトリ・トラバーサルです。HTTPヘッダ・インジェクションは、改行を含む値でレスポンスヘッダを不正に追加する攻撃です。"}, {"t": "カスタムデータ属性", "q": "要素に、ページ独自のデータを持たせるための属性として、正しい名前の付け方はどれか。", "c": ["x- で始める(例: x-price)", "data- で始める(例: data-price)", "好きな名前を付けてよい(例: price)", "custom- で始める(例: custom-price)"], "k": 1, "e": "カスタムデータ属性は、data- で始まる名前にします。JavaScriptでは、要素の dataset プロパティから読み書きできます(data-price なら dataset.price)。"}, {"t": "Data URIスキーム", "q": "「data:image/png;base64,iVBORw0KGgo…」のように書く Data URI スキームの説明として、適切なものはどれか。", "c": ["画像などのデータをBase64でエンコードして、URLの中に直接埋め込む", "画像を、別のサーバからダウンロードする", "画像を暗号化して送る", "画像をブラウザのキャッシュから削除する"], "k": 0, "e": "Data URIスキームは、データそのものをURLの中に書き込みます。小さな画像なら、別のファイルを取りに行くリクエストを減らせます。Base64はエンコードで、暗号化ではありません。;base64 を付けない場合は、テキストをそのまま(必要に応じてURLエンコードして)書くこともできます。"}, {"t": "Ajax", "q": "Ajaxの説明として適切なものはどれか。", "c": ["JavaScriptで、サーバと非同期に通信し、ページ全体を読み込み直さずに、一部だけを更新する", "サーバ側で、HTMLを一度だけ生成して配る", "ブラウザの履歴を消す", "画像を圧縮して、表示を速くする"], "k": 0, "e": "Ajaxは、XMLHttpRequest や fetch などで、裏でサーバと通信し、ページの一部だけを書き換える手法です。"}, {"t": "画像ファイルの形式", "q": "写真の保存に向いている、非可逆圧縮(元のデータに完全には戻らない圧縮)の画像形式はどれか。", "c": ["BMP", "GIF", "PNG", "JPEG"], "k": 3, "e": "JPEGは非可逆圧縮で、写真に向いています。PNGは可逆圧縮で、透過も使えます。GIFは使える色が256色までで、アニメーションも作れます。BMPは、基本的に圧縮しない形式です。"}, {"t": "302", "q": "リソースが一時的に別のURLへ移動したことを表すステータスコードはどれか。", "c": ["200", "301", "404", "302"], "k": 3, "e": "302は Found で、一時的な移動を表します。恒久的な移動は301です。"}, {"t": "401と403", "q": "アクセスにユーザー認証が必要なのに、認証されていないリクエストに対して返す、ステータスコードはどれか。", "c": ["500", "401", "404", "301"], "k": 1, "e": "401は Unauthorized で、認証が必要なことを表します。Basic認証などで、ブラウザがIDとパスワードの入力画面を出すきっかけになります。403は Forbidden で、リクエストは理解できたが、アクセスを許可しないことを表します。"}, {"t": "503", "q": "サーバが、一時的な過負荷やメンテナンスのために、リクエストを処理できないときのステータスコードはどれか。", "c": ["404", "400", "301", "503"], "k": 3, "e": "503は Service Unavailable で、サービスが一時的に利用できないことを表します。400はリクエストの形式が正しくない、404はリソースが見つからないことです。"}, {"t": "DELETEメソッド", "q": "サーバ上のリソースを削除するように要求するHTTPメソッドはどれか。", "c": ["POST", "DELETE", "HEAD", "GET"], "k": 1, "e": "DELETEは、指定したリソースの削除を要求します。GETは取得、HEADはヘッダだけの取得、POSTはデータの送信に使います。"}, {"t": "PUTメソッド", "q": "リクエストのボディの内容で、URLで指定したリソースを作成、または置き換えるHTTPメソッドはどれか。", "c": ["HEAD", "PUT", "GET", "DELETE"], "k": 1, "e": "PUTは、指定したURLのリソースを、リクエストの内容で作成または置き換えます。"}, {"t": "HTTP/2", "q": "HTTP/2の特徴として、適切なものはどれか。", "c": ["1つの接続の中で、複数のリクエストとレスポンスを並行してやり取りできる(多重化)", "ヘッダの圧縮ができない", "1つのリクエストごとに、必ず新しい接続を作る", "通信の内容は、必ず人間が読めるテキスト形式で送られる"], "k": 0, "e": "HTTP/2は、1つの接続で複数のやり取りを並行して行う多重化ができます。通信の内容はバイナリ形式で、ヘッダも圧縮されます。HTTP/1.1と同じメソッドやステータスコードを使えます。"}, {"t": "Cache-Controlヘッダ", "q": "ブラウザやキャッシュサーバが、レスポンスをどのように保存してよいかを指示する、HTTPヘッダはどれか。", "c": ["Content-Language", "Accept", "Authorization", "Cache-Control"], "k": 3, "e": "Cache-Controlは、キャッシュの扱い(保存してよいか、何秒間有効か、など)を指示します。Expiresも有効期限を指定します。Content-Languageは内容の言語、Authorizationは認証情報、Acceptは受け取れる形式を表すヘッダです。"}, {"t": "Acceptヘッダ", "q": "クライアントが、受け取れるデータの形式(メディアタイプ)をサーバに伝える、リクエストヘッダはどれか。", "c": ["Content-Language", "Accept", "Set-Cookie", "Expires"], "k": 1, "e": "Acceptヘッダで、受け取れるメディアタイプ(text/html など)を伝えます。Expiresはキャッシュの有効期限、Set-CookieはCookieを保存させるレスポンスヘッダです。"}, {"t": "URLの構成", "q": "URL「https://www.example.com:8080/path/index.html?id=3#top」で、クエリ文字列にあたる部分はどれか。", "c": ["8080", "id=3", "/path/index.html", "top"], "k": 1, "e": "?の後ろ、#の前の「id=3」がクエリ文字列です。8080はポート番号、/path/index.html はパス、#の後ろの「top」はフラグメント(ページ内の位置)です。"}], "ut": true, "lvn": "公式の出題範囲 1.1(レベル1 Ver2.5)"},
{"id": "l1a2", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "Webの基礎知識(HTTP・HTMLの書式・Web技術)(2/2)", "dm": 1.5, "ps": [{"t": "パーセントエンコーディング", "q": "URLに日本語を含めるとき、「あ」をUTF-8でパーセントエンコーディングしたものはどれか。", "c": ["%E3%81%81", "%30%42", "%E3%81%82", "%82%A0"], "k": 2, "e": "「あ」のUTF-8は、3バイト(E3 81 82)で、各バイトを %XX にします。%82%A0 は、同じ「あ」をShift_JISで表したものです。"}, {"t": "Cookieのsecure属性", "q": "Cookieに Secure 属性を付けたときの動作として、適切なものはどれか。", "c": ["ブラウザを閉じても、Cookieが削除されなくなる", "HTTPSで接続しているときだけ、Cookieを送信する", "別のドメインにも、Cookieを送信する", "JavaScriptからCookieを読み出せなくなる"], "k": 1, "e": "Secure属性を付けると、暗号化されたHTTPSの通信でだけCookieが送られます。JavaScriptから読み出せなくするのは、HttpOnly属性です。"}, {"t": "CookieのHttpOnly属性", "q": "Cookieに HttpOnly 属性を付けたときの動作として、適切なものはどれか。", "c": ["JavaScriptの document.cookie から、Cookieを読み出せなくなる", "Cookieが、HTTPではなく別の通信方式で送られる", "ブラウザを閉じると、必ずCookieが削除される", "HTTPSで接続しているときだけ、Cookieを送信する"], "k": 0, "e": "HttpOnly属性は、スクリプトからCookieを読めなくします。XSSで、セッションIDなどが盗まれるリスクを減らせます。"}, {"t": "サーバ証明書", "q": "HTTPSで、接続先のサーバが本物であることを確かめるために、サーバが提示するものはどれか。", "c": ["ブラウザのキャッシュ", "利用者のパスワード", "Cookieに保存したセッションID", "認証局(CA)が発行したサーバ証明書"], "k": 3, "e": "サーバは、認証局が発行した証明書を提示します。ブラウザは、それが信頼できる認証局の署名であることなどを確かめます。"}, {"t": "Digest認証", "q": "パスワードそのものを送らず、サーバから受け取った値とパスワードから計算したハッシュ値を送って認証する、HTTPの認証方式はどれか。", "c": ["Basic認証", "CAPTCHA", "フォーム認証", "Digest認証"], "k": 3, "e": "Digest認証は、パスワードのハッシュ値を使います。Basic認証は、「ユーザー名:パスワード」をBase64で変換して送るだけです。フォーム認証は、HTMLのフォームを使う方式で、HTTPで規定された認証方式ではありません。"}, {"t": "ステートレス", "q": "HTTPはステートレスなプロトコルである。この性質から、ログイン状態を保つために使われるものはどれか。", "c": ["Cookie(セッションID)", "ファビコン", "DNS", "MIMEタイプ"], "k": 0, "e": "HTTPは、リクエストごとに独立していて、前の状態を覚えていません。そのため、サーバが発行したセッションIDをCookieに保存し、リクエストのたびに送って、利用者を識別します。"}, {"t": "メタ情報の位置", "q": "文字エンコーディングを宣言するmeta要素の書き方として、HTMLの仕様が求めているものはどれか。", "c": ["必ず title要素より後ろに書く", "body要素の末尾に書く", "ファイルの最後の1行に書く", "文書の先頭から1024バイト以内に収める"], "k": 3, "e": "HTMLの仕様では、文字エンコーディングの宣言は、文書の先頭から1024バイト以内に収めるよう求めています。ふつうは、head要素の最初のほうに書きます。"}, {"t": "&amp;", "q": "HTMLで、「&」という文字を表示するための文字参照はどれか。", "c": ["&gt;", "&quot;", "&lt;", "&amp;"], "k": 3, "e": "&amp; は「&」です。&lt; は「<」、&gt; は「>」、&quot; は「\"」を表します。"}, {"t": "&nbsp;", "q": "HTMLでは、連続した半角スペースは、通常1つにまとめて表示される。改行されない空白(ノーブレークスペース)を表す文字参照はどれか。", "c": ["&wspace;", "&sp1;", "&nbsp;", "&nospace;"], "k": 2, "e": "&nbsp; は、改行されない空白です。連続して書くと、その数だけ空白が表示されます。"}, {"t": "数値文字参照", "q": "「&#169;」と書いたとき、表示される文字はどれか。", "c": ["¥", "™", "©", "®"], "k": 2, "e": "「&#数字;」は、Unicodeのコードポイントを10進数で書く数値文字参照です。169は ©(著作権記号)です。16進数なら &#xA9; と書きます。"}, {"t": "ファビコンの指定", "q": "ブラウザのタブなどに表示するアイコン(ファビコン)を指定する書き方として、正しいものはどれか。", "c": ["<meta name=\"icon\" content=\"favicon.ico\">", "<img rel=\"icon\" src=\"favicon.ico\">", "<link rel=\"favicon\" href=\"favicon.ico\">", "<link rel=\"icon\" href=\"favicon.ico\">"], "k": 3, "e": "link要素の rel=\"icon\" で、ファビコンを指定します。head要素の中に書きます。"}, {"t": "description", "q": "検索結果に表示されることがある、ページの概要を指定する書き方として、適切なものはどれか。", "c": ["<meta name=\"description\" content=\"ページの概要\">", "<link rel=\"description\" href=\"ページの概要\">", "<meta charset=\"ページの概要\">", "<meta name=\"summary\" content=\"ページの概要\">"], "k": 0, "e": "meta要素の name=\"description\" で、ページの概要を指定します。"}, {"t": "base要素", "q": "文書内の相対URLを解決するときの基準となるURLを指定する要素はどれか。", "c": ["base", "a", "head", "link"], "k": 0, "e": "base要素を head の中に書くと、href属性のURLが、相対URLの基準になります。"}, {"t": "コメント", "q": "HTMLのコメントの書き方として、正しいものはどれか。", "c": ["// コメント", "# コメント", "/* コメント */", "<!-- コメント -->"], "k": 3, "e": "HTMLでは、<!-- と --> で囲んだ部分がコメントになり、画面に表示されません。/* */ はCSSやJavaScript、// はJavaScriptのコメントです。"}, {"t": "論理属性", "q": "次のHTMLを表示したとき、チェックボックスの状態として、正しいものはどれか。\n<input type=\"checkbox\" checked=\"false\">", "c": ["チェックボックスが表示されない", "エラーになり、何も表示されない", "チェックされていない状態になる", "チェックされた状態になる"], "k": 3, "e": "checked は、書いてあるかどうかで意味が決まる論理属性で、値は関係ありません。\"false\" と書いても、チェックされた状態になります。チェックしない状態にするには、属性ごと書かないようにします。"}, {"t": "CSRF対策", "q": "クロスサイト・リクエスト・フォージェリ(CSRF)の対策として、適切なものはどれか。", "c": ["フォームに推測されにくいトークンを埋め込み、サーバでリクエストごとに照合する", "SQL文を、プレースホルダを使って組み立てる", "ファイル名の「../」を取り除く", "出力する文字の<と>を、文字参照に置き換える"], "k": 0, "e": "CSRF対策は、トークンの照合などで、リクエストが利用者の意図したものであることを確かめます。文字参照への置き換えはXSS、プレースホルダはSQLインジェクション、「../」の除去はディレクトリ・トラバーサルの対策です。"}, {"t": "SQLインジェクション対策", "q": "SQLインジェクションの対策として、最も適切なものはどれか。", "c": ["出力するHTMLの特殊文字を、文字参照に置き換える", "SQL文を、プレースホルダ(バインド変数)を使って組み立てる", "Cookieに Secure 属性を付ける", "リクエストに、推測されにくいトークンを付ける"], "k": 1, "e": "プレースホルダを使うと、入力値が、SQL文の一部ではなく、値として扱われます。Secure属性は、Cookieを暗号化された通信でだけ送るためのものです。HTMLの特殊文字の置き換えはXSS、トークンの付加はCSRFの対策です。"}, {"t": "XSS対策", "q": "クロスサイト・スクリプティング(XSS)の対策として、適切なものはどれか。", "c": ["出力するときに、<、>、&、\" などを文字参照に置き換える(エスケープする)", "パスワードをBase64で変換して保存する", "フォームにトークンを埋め込む", "SQL文を、プレースホルダを使って組み立てる"], "k": 0, "e": "利用者の入力をHTMLに出力するときに、特殊文字をエスケープすると、スクリプトとして実行されません。Base64は暗号化ではなく、パスワードの保護にはなりません。"}, {"t": "HTTPヘッダ・インジェクション", "q": "外部から受け取った値を、LocationやSet-Cookieなどのレスポンスヘッダに出力するとき、値に含まれる改行を悪用して、ヘッダを不正に追加する攻撃はどれか。", "c": ["ディレクトリ・トラバーサル", "クロスサイト・スクリプティング", "SQLインジェクション", "HTTPヘッダ・インジェクション"], "k": 3, "e": "改行コード(CRLF)を含む値で、ヘッダの区切りを偽装する攻撃です。対策は、改行を含む値を拒否または除去することです。"}, {"t": "DOM", "q": "DOM(Document Object Model)の説明として、適切なものはどれか。", "c": ["HTML文書を、サーバ側で生成するための仕組み", "HTML文書を、要素や文字などのノードのツリー構造で表し、JavaScriptから操作できるようにした仕組み", "CSSを、別のファイルに分ける仕組み", "Webサーバと、データベースを接続する仕組み"], "k": 1, "e": "DOMは、文書をツリー構造のオブジェクトとして扱い、JavaScriptで要素の取得、追加、削除、書き換えができます。"}, {"t": "MVC", "q": "Webアプリケーションの設計で使われる、MVCアーキテクチャの説明として、適切なものはどれか。", "c": ["CSSを、基本、レイアウト、装飾の3つに分ける", "処理を、データを扱うモデル、表示を担当するビュー、入力を受け付けて制御するコントローラに分ける", "サーバを、Web、アプリケーション、データベースの3台に分ける", "画面を、ヘッダ、本文、フッタの3つに分ける"], "k": 1, "e": "MVCは Model(データと処理)、View(表示)、Controller(入力の受付と制御)の略です。役割を分けて、変更しやすくします。"}, {"t": "インタレース", "q": "画像のインタレース(インターレース)形式の特徴として、適切なものはどれか。", "c": ["画像に、透明な部分を設定できる", "画像の一部分ずつが、上から順にくっきりと表示される", "画像が、自動で拡大・縮小される", "読み込みの途中でも、粗い画像が全体に先に表示され、徐々に細部がはっきりする"], "k": 3, "e": "インタレースは、全体のおおまかな画像を先に見せて、読み込みが進むほど細かくなる方式です。GIFやPNGで使われ、JPEGではプログレッシブJPEGが同じ考え方です。"}, {"t": "PNG", "q": "Webで広く使われる画像形式のうち、半透明を含む透過(アルファチャンネル)に対応し、フルカラーの画像を可逆圧縮で保存できるものはどれか。", "c": ["GIF", "PNG", "JPEG", "BMP"], "k": 1, "e": "PNGは、可逆圧縮で、アルファチャンネルによる半透明を扱えます。GIFは256色までで、透明か不透明かの2択です。JPEGは非可逆圧縮で、透過に対応していません。"}, {"t": "マイクロデータ", "q": "itemscope属性や itemprop属性を使って、商品名や価格などの意味を、機械が読み取れる形でHTMLに付ける仕組みはどれか。", "c": ["リセットCSS", "マイクロデータ", "ベンダープレフィックス", "カスタムデータ属性"], "k": 1, "e": "マイクロデータは、HTMLの要素に、構造化されたデータの意味を付けて、検索エンジンなどが読み取りやすくする仕組みです。カスタムデータ属性(data-*)は、ページ独自のデータを持たせる属性で、意味の語彙は決まっていません。"}, {"t": "Base64", "q": "Base64の説明として、適切なものはどれか。", "c": ["バイナリデータを、英数字などの印字できる文字だけの文字列に変換する符号化の方式で、暗号化ではない", "データを、鍵を使って暗号化する方式", "データを、ファイルサイズが小さくなるように圧縮する方式", "データから、元に戻せない固定長の値を求める方式"], "k": 0, "e": "Base64は、バイナリデータを64種類の文字で表す符号化です。データは約1.33倍に増え、誰でも元に戻せるので、暗号化ではありません。Data URIスキームやBasic認証で使われます。「元に戻せない固定長の値を求める」方式はハッシュ関数、「鍵を使って」変換する方式は暗号化、「サイズが小さくなる」方式は圧縮です。"}], "ut": true, "lvn": "公式の出題範囲 1.1(レベル1 Ver2.5)"},
{"id": "l1b", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "CSS(基本・デザイン・優先順位)(1/3)", "dm": 1.5, "ps": [{"t": "外部スタイルシート", "q": "HTMLから外部のCSSファイル style.css を読み込む書き方として、正しいものはどれか。", "c": ["<script href=\"style.css\"></script>", "<meta stylesheet=\"style.css\">", "<style src=\"style.css\"></style>", "<link rel=\"stylesheet\" href=\"style.css\">"], "k": 3, "e": "外部のCSSファイルは、head の中に link 要素(rel=\"stylesheet\")で読み込みます。style 要素は、HTMLの中にCSSを直接書くときに使います。CSSの中からは @import でも読み込めます。"}, {"t": "IDセレクタ", "q": "id=\"main\" の要素を選ぶセレクタはどれか。", "c": [".main", "main", "*main", "#main"], "k": 3, "e": "#はIDセレクタ、.はクラスセレクタです。main だけだと、main要素を選ぶタイプセレクタになります。* はすべての要素を選ぶユニバーサルセレクタです。"}, {"t": "属性セレクタ", "q": "CSSの「a[target=\"_blank\"] { ... }」で選ばれる要素はどれか。", "c": ["a要素の中にあるすべての要素", "target属性を持たない a要素", "target属性の値が _blank である a要素", "_blank というクラスの a要素"], "k": 2, "e": "[属性名=\"値\"] は属性セレクタで、属性の値が一致する要素を選びます。target属性があるかどうかだけで選ぶなら a[target] と書きます。"}, {"t": "結合子", "q": "CSSの「h2 + p」で選ばれる要素はどれか。", "c": ["h2要素の直接の子であるp要素", "h2要素とp要素の両方", "h2要素の中にある、すべてのp要素", "h2要素の直後にある、兄弟のp要素"], "k": 3, "e": "+ は隣接兄弟結合子で、直後の兄弟要素を選びます。子孫は半角スペース(h2 p)、直接の子は >(h2 > p)、両方を選ぶのはカンマ(h2, p)です。"}, {"t": "疑似要素", "q": "要素の内容の前に、CSSでコンテンツを挿入するときに使うものはどれか。", "c": [":hover", "::before", ":focus", ":first-child"], "k": 1, "e": "::before は疑似要素で、content プロパティと組み合わせて、要素の内容の前にコンテンツを追加します。:hover、:first-child、:focus は、要素の状態や位置で選ぶ疑似クラスです。"}, {"t": "セレクタの優先度", "q": "次のHTMLとCSSで、文字の色は何色になるか。\n\nHTML: <p id=\"x\" class=\"y\">テキスト</p>\nCSS:\np { color: blue; }\n#x { color: red; }\n.y { color: green; }", "c": ["赤(red)", "緑(green)", "黒(既定の色)", "青(blue)"], "k": 0, "e": "セレクタの優先度(詳細度)は、IDセレクタ > クラスセレクタ > タイプセレクタの順です。書いた順番より詳細度が優先されるので、#x の赤になります。"}, {"t": "!important", "q": "次のHTMLとCSSで、文字の色は何色になるか。\n\nHTML: <p id=\"x\" class=\"y\">テキスト</p>\nCSS:\n#x { color: red; }\n.y { color: green !important; }", "c": ["緑(後に書いた宣言が優先されるから)", "緑(!important を付けた宣言が優先されるから)", "黒(どちらも適用されないから)", "赤(IDセレクタの方が詳細度が高いから)"], "k": 1, "e": "!important を付けた宣言は、詳細度に関係なく、付けていない宣言より優先されます。そのため、IDセレクタより詳細度が低い .y の緑になります。書いた順番が効くのは、重要度も詳細度も同じときだけです。"}, {"t": "インラインスタイル", "q": "!important を使わないとき、同じ要素に対するスタイルの中で最も優先されるのはどれか。", "c": ["IDセレクタで書いたスタイル", "外部スタイルシートの一番最後に書いたスタイル", "style属性で書いたスタイル(インラインスタイル)", "クラスセレクタで書いたスタイル"], "k": 2, "e": "style属性のスタイルは、どのセレクタで書いたスタイルよりも優先されます。セレクタで書いたスタイルでこれを上書きするには、!important を付けます。"}, {"t": "ボックスモデル", "q": "次のCSSで、要素の枠線(border)の外側までの幅は何pxになるか。box-sizing は指定していない(初期値の content-box)ものとする。\n\nwidth: 200px;\npadding: 10px;\nborder: 5px solid #000;\nmargin: 20px;", "c": ["270px", "200px", "230px", "220px"], "k": 2, "e": "content-box では、width は中身の幅です。左右の padding(10px×2)と border(5px×2)を足して、200+20+10=230px です。margin は枠線の外側の余白なので含めません。"}, {"t": "displayとvisibility", "q": "「visibility: hidden」の説明として、適切なものはどれか。", "c": ["要素は見えなくなるが、要素の場所(領域)は残る", "要素は見えなくなり、場所も詰められる", "要素が半透明になる", "要素が画面の外へ移動する"], "k": 0, "e": "visibility: hidden は、見えなくするだけで、場所は残ります。display: none は、要素がないものとして扱われ、場所も詰められます。半透明は opacity で指定します。"}, {"t": "角丸", "q": "要素の枠の角を丸くするプロパティはどれか。", "c": ["border-radius", "box-shadow", "outline", "border-style"], "k": 0, "e": "border-radius で角を丸くします。border-style は枠線の種類、box-shadow は影を付けるプロパティです。"}, {"t": "transform", "q": "要素を45度回転させる指定はどれか。", "c": ["transform: scale(45deg);", "transform: translate(45deg);", "transform: rotate(45deg);", "transform: skew(45px);"], "k": 2, "e": "rotate は回転です。translate は移動、scale は拡大・縮小、skew は傾斜(ゆがみ)です。"}, {"t": "アニメーションの繰り返し", "q": "CSSアニメーションを、止まらずに繰り返し続けるようにする指定はどれか。", "c": ["animation-iteration-count: infinite;", "animation-direction: infinite;", "animation-delay: infinite;", "animation-duration: infinite;"], "k": 0, "e": "繰り返し回数は animation-iteration-count で指定し、infinite で無限に繰り返します。duration は1回の長さ、delay は開始までの待ち時間、direction は再生の向きです。"}, {"t": "段組み", "q": "文章を3段の段組み(マルチカラム)にするプロパティはどれか。", "c": ["float: 3;", "column-count: 3;", "columns-gap: 3;", "z-index: 3;"], "k": 1, "e": "column-count で段の数を指定します。段と段の間隔は column-gap、段の間の線は column-rule で指定します。"}, {"t": "トランジション", "q": "クラス btn の要素の背景色(background-color)が変わるとき、0.3秒かけてなめらかに変わるように、transition プロパティを使ってCSSを記述しなさい。", "code": ".btn {\n  transition: background-color 0.3s;\n}", "e": "transition に、変化させるプロパティ名と時間を書きます。0.3s は 300ms とも書けます。(参考)transition は一括指定のプロパティで、transition-property と transition-duration に分けて書くこともできます。", "m": 3}, {"t": "CSSの記述", "q": "クラス note の要素の、文字色を #333、背景色を #eee、文字の大きさを 14px にするCSSを記述しなさい。", "code": ".note {\n  color: #333;\n  background-color: #eee;\n  font-size: 14px;\n}", "e": "文字色は color、背景色は background-color(background でも可)、文字の大きさは font-size です。プロパティの順番は問いません。", "m": 3}, {"t": ":first-child", "q": "CSSの「li:first-child { color: red; }」で、選ばれる要素はどれか。", "c": ["li要素の中の、最初の子要素", "親要素の最初の子であるli要素", "li要素の直前にある要素", "すべてのli要素のうち、最初の1つだけ"], "k": 1, "e": ":first-child は、親の最初の子であるという条件の疑似クラスです。リストごとに、最初のli要素が選ばれます。"}, {"t": ":nth-child", "q": "CSSの「tr:nth-child(even) { background: #eee; }」で、選ばれる要素はどれか。", "c": ["最初のtr要素", "奇数番目にあたるtr要素", "すべてのtr要素", "親要素の子のうち、偶数番目にあたるtr要素"], "k": 3, "e": ":nth-child(even) は偶数番目、(odd) は奇数番目の子です。表の縞模様(ストライプ)に使います。"}, {"t": "::first-letter", "q": "段落の最初の1文字だけに、スタイルを付けるときに使うものはどれか。", "c": ["p::before", "p:first-child", "p > letter", "p::first-letter"], "k": 3, "e": "::first-letter は、ブロックの最初の文字を選ぶ疑似要素です。::first-line なら、最初の行です。"}, {"t": ":checked", "q": "チェックされているチェックボックスやラジオボタンを選ぶ、疑似クラスはどれか。", "c": [":focus", ":hover", ":active", ":checked"], "k": 3, "e": ":checked は、チェックされた入力要素を選びます。:hover はマウスが乗った状態、:focus はフォーカスされた状態、:active は押されている状態です。"}, {"t": "一般兄弟結合子", "q": "CSSの「h2 ~ p { color: red; }」で、選ばれる要素はどれか。", "c": ["h2要素の直後にあるp要素だけ", "h2要素の後ろにある、同じ親を持つすべてのp要素", "h2要素の前にあるp要素", "h2要素の中にあるp要素"], "k": 1, "e": "~ は一般兄弟結合子で、後ろにある同じ親の兄弟要素すべてを選びます。直後だけを選ぶのは、隣接兄弟結合子(+)です。"}, {"t": "ユニバーサルセレクタ", "q": "CSSの「* { margin: 0; }」の意味として、適切なものはどれか。", "c": ["body要素だけの余白を0にする", "クラスが付いた要素の余白を0にする", "すべての要素の外側の余白を0にする", "最後の要素の余白を0にする"], "k": 2, "e": "* は、すべての要素を選ぶユニバーサルセレクタです。"}, {"t": "属性セレクタ($=)", "q": "CSSの「a[href$=\".pdf\"] { ... }」で、選ばれる要素はどれか。", "c": ["href属性の値が「.pdf」で終わるa要素", "href属性の値が「.pdf」で始まるa要素", "クラスが pdf のa要素", "href属性の値に「.pdf」を含まないa要素"], "k": 0, "e": "[属性$=\"値\"] は、値が終わる部分で一致するものを選びます。^= は始まる部分、*= は含む部分です。"}, {"t": "属性セレクタ(^=)", "q": "CSSの「a[href^=\"https\"] { ... }」で、選ばれる要素はどれか。", "c": ["href属性の値が「https」で始まるa要素", "クラスが https のa要素", "href属性の値に「https」を含まないa要素", "href属性の値が「https」で終わるa要素"], "k": 0, "e": "^= は、値が先頭で一致するものを選びます。外部への安全な接続のリンクに印を付けるなどに使えます。"}], "ut": true, "lvn": "公式の出題範囲 1.2(レベル1 Ver2.5)"},
{"id": "l1b2", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "CSS(基本・デザイン・優先順位)(2/3)", "dm": 1.5, "ps": [{"t": "インライン要素の幅", "q": "span要素(初期値は display: inline)に、width: 200px; と指定したとき、表示はどうなるか。", "c": ["span要素が、強制的に改行される", "幅の指定は、反映されない", "幅が200pxになる", "エラーになり、スタイル全体が無効になる"], "k": 1, "e": "インライン要素には、width や height が効きません。display: inline-block や display: block にすれば、反映されます。ただし、img要素などの置換要素は、インラインでも幅と高さを指定できます。"}, {"t": "marginの短縮記法(4つ)", "q": "CSSの「margin: 10px 20px 30px 40px;」で、外側の余白の指定として、正しいものはどれか。", "c": ["上10px、右30px、下20px、左40px", "左10px、上20px、右30px、下40px", "上10px、左20px、下30px、右40px", "上10px、右20px、下30px、左40px"], "k": 3, "e": "4つの値は、上、右、下、左の時計回りの順です。"}, {"t": "paddingの短縮記法(2つ)", "q": "CSSの「padding: 10px 20px;」で、内側の余白の指定として、正しいものはどれか。", "c": ["上下20px、左右10px", "上下10px、左右20px", "上が10px、残りの3辺が20px", "上と右が10px、下と左が20px"], "k": 1, "e": "値が2つのときは、1つ目が上下、2つ目が左右です。"}, {"t": "position: absolute", "q": "「position: absolute」の要素は、何を基準にして位置が決まるか。", "c": ["常に、画面(ビューポート)", "常に、body要素", "position が static 以外の、最も近い祖先要素(なければ、文書の初期の領域)", "常に、直前の兄弟要素"], "k": 2, "e": "absolute は、position が static 以外(relative など)の最も近い祖先要素を基準にします。祖先に該当する要素がなければ、最初の包含ブロックが基準です。画面に固定するのは、position: fixed です。(transform などを指定した祖先も基準になることがありますが、基本は position が static 以外の祖先です。)"}, {"t": "position: fixed", "q": "「position: fixed」の要素の説明として、適切なものはどれか。", "c": ["親要素を基準にして位置が決まり、親と一緒にスクロールする", "要素が、画面の外に隠れる", "通常の位置のまま、他の要素に重ならない", "ビューポート(画面)を基準にして位置が決まり、スクロールしても同じ位置に表示される"], "k": 3, "e": "fixed は、画面を基準に位置が固定されるので、ヘッダを常に表示するなどに使えます。"}, {"t": "clear", "q": "float で回り込んでいる要素の下に、次の要素を回すために、その要素に指定するプロパティはどれか。", "c": ["z-index", "visibility", "opacity", "clear"], "k": 3, "e": "clear: both; などで、float した要素の回り込みを解除し、その下に表示させます。"}, {"t": "z-index", "q": "z-indexの説明として、適切なものはどれか。", "c": ["要素の表示を、画面の外へずらす", "要素が重なるときの前後の順序を指定し、値が大きいほど手前に表示される(position が static 以外の要素などで有効)", "要素の幅を指定する", "要素の透明度を指定する"], "k": 1, "e": "z-index が大きい要素が、手前に表示されます。position が static 以外の要素や、flexコンテナの子要素などに指定できます。"}, {"t": "overflow: auto", "q": "「overflow: auto」の説明として、適切なものはどれか。", "c": ["はみ出した部分を、隠す", "内容がはみ出すときだけ、スクロールバーを表示する", "はみ出した部分を、そのまま表示する", "常に、スクロールバーを表示する"], "k": 1, "e": "auto は、必要なときだけスクロールバーを出します。scroll は常に表示、hidden ははみ出しを隠す、visible ははみ出しをそのまま表示(初期値)です。"}, {"t": "Flexbox(中央寄せ)", "q": "display: flex の親要素で、子要素を主軸方向(横方向)の中央に寄せるプロパティと値はどれか。", "c": ["flex-center: true", "text-align: middle", "align-content: center", "justify-content: center"], "k": 3, "e": "justify-content は、主軸方向の配置です。交差軸(縦方向)の配置は、align-items で指定します。"}, {"t": "flex-direction", "q": "flexコンテナの子要素を、縦方向に並べるための指定はどれか。", "c": ["flex-direction: row", "flex-direction: column", "align-items: vertical", "flex-wrap: wrap"], "k": 1, "e": "flex-direction は、主軸の向きを決めます。初期値の row は横並び、column は縦並びです。"}, {"t": "max-widthプロパティ", "q": "「max-width: 600px」の説明として、適切なものはどれか。", "c": ["幅は、最小でも600pxになる", "幅は、必ずちょうど600pxになる", "高さの最大値が600pxになる", "幅は、最大でも600pxまでで、それ以上には広がらない"], "k": 3, "e": "max-width は幅の上限、min-width は幅の下限です。"}, {"t": "opacity", "q": "「opacity: 0.5」の説明として、適切なものはどれか。", "c": ["文字の色だけが、半透明になる", "要素全体(内容や子要素も含む)が、半透明になる", "要素が、半分の大きさになる", "背景の色だけが、半透明になる"], "k": 1, "e": "opacity は、要素全体の不透明度です。背景色だけを半透明にしたいときは、rgba() で指定します。"}, {"t": "色の指定", "q": "CSSの「color: #fff;」が表す色はどれか。", "c": ["黒", "赤", "白", "透明"], "k": 2, "e": "#fff は、#ffffff の短縮形で、赤・緑・青のすべてが最大なので、白です。黒は #000 です。"}, {"t": "background-size", "q": "「background-size: cover」の説明として、適切なものはどれか。", "c": ["縦横の比率を保ったまま、背景画像が要素全体を覆うように拡大・縮小する(はみ出した部分は表示されない)", "背景画像が、すべて収まるように縮小される", "背景画像を、元の大きさのまま左上に置く", "背景画像を、繰り返し並べる"], "k": 0, "e": "cover は、要素を隙間なく覆います。画像全体が収まるようにするのは、contain です。"}, {"t": "background-repeat", "q": "背景画像を、横方向にだけ繰り返して並べる指定はどれか。", "c": ["background-repeat: round-x", "background-repeat: repeat-y", "background-repeat: repeat-x", "background-repeat: no-repeat"], "k": 2, "e": "repeat-x は横方向、repeat-y は縦方向、no-repeat は繰り返しません(初期値は repeat で縦横に繰り返します)。"}, {"t": "グラデーション", "q": "「background-image: linear-gradient(red, blue);」の表示として、適切なものはどれか。", "c": ["左が赤で、右に向かって青に変化する", "上が赤で、下に向かって青に変化する", "全体が、赤と青の縞模様になる", "中心が赤で、外に向かって青に変化する"], "k": 1, "e": "linear-gradient は、方向を省略すると、上から下に向かうグラデーションです。中心から広がるものは、radial-gradient です。"}, {"t": "box-shadow", "q": "「box-shadow: 2px 4px 6px #000;」で、「6px」が表すものはどれか。", "c": ["影のぼかしの大きさ", "影の大きさ(広がり)", "影の水平方向のずれ", "影の垂直方向のずれ"], "k": 0, "e": "値は順に、水平方向のずれ(2px)、垂直方向のずれ(4px)、ぼかし(6px)、色です。"}, {"t": "border-style", "q": "要素の枠線を、破線にするための指定はどれか。", "c": ["border-style: double", "border-style: dotted", "border-style: dashed", "border-style: solid"], "k": 2, "e": "dashed は破線、dotted は点線、solid は実線、double は二重線です。"}, {"t": "generic-family", "q": "「font-family: Arial, sans-serif;」の「sans-serif」は、何を表しているか。", "c": ["Arialの別名", "フォントファイルの名前", "ジェネリックフォントファミリ(総称)で、Arialが使えないときに、ゴシック体系のフォントが使われる", "文字の太さの指定"], "k": 2, "e": "sans-serif は、ゴシック体系(飾りのない書体)を表す総称です。ほかに、serif(明朝体系)、monospace(等幅)などがあります。"}, {"t": "font-weight", "q": "「font-weight: bold」と同じ太さを表す、数値はどれか。", "c": ["100", "900", "400", "700"], "k": 3, "e": "normal は400、bold は700です。"}, {"t": "@font-face", "q": "Webフォントとして、サーバにあるフォントファイルを使うために、フォント名とファイルを指定する規則はどれか。", "c": ["@keyframes", "@import", "@media", "@font-face"], "k": 3, "e": "@font-face に、font-family(使うときの名前)と src(ファイルのURL)を書いて、Webフォントを定義します。"}, {"t": "text-indent", "q": "段落の最初の行の先頭を、字下げするプロパティはどれか。", "c": ["text-align", "letter-spacing", "line-height", "text-indent"], "k": 3, "e": "text-indent: 1em; のように指定します。text-align は行の揃え、line-height は行の高さ、letter-spacing は文字の間隔です。"}, {"t": "line-height", "q": "「line-height: 1.5」の説明として、適切なものはどれか。", "c": ["行の高さが、その要素の文字の大きさの1.5倍になる", "行の高さが、1.5pxになる", "行の幅が、1.5倍になる", "文字の大きさが、1.5倍になる"], "k": 0, "e": "単位のない数値は、文字の大きさに対する倍率です。"}, {"t": "text-decoration", "q": "リンクの下線を消すための指定はどれか。", "c": ["text-decoration: none", "text-transform: none", "text-indent: none", "font-style: none"], "k": 0, "e": "text-decoration は、下線(underline)や取り消し線(line-through)などの装飾を指定します。none で装飾をなくします。"}], "ut": true, "lvn": "公式の出題範囲 1.2(レベル1 Ver2.5)"},
{"id": "l1b3", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "CSS(基本・デザイン・優先順位)(3/3)", "dm": 1.5, "ps": [{"t": "letter-spacing", "q": "文字と文字の間隔を指定するプロパティはどれか。", "c": ["letter-spacing", "text-indent", "line-height", "word-spacing"], "k": 0, "e": "letter-spacing は文字の間隔です。word-spacing は単語の間隔、line-height は行の高さです。"}, {"t": "text-transform", "q": "英字をすべて大文字で表示するための指定はどれか。", "c": ["text-transform: capitalize", "font-variant: normal", "text-transform: uppercase", "text-transform: lowercase"], "k": 2, "e": "uppercase は大文字、lowercase は小文字、capitalize は単語の先頭だけ大文字にします。"}, {"t": "white-space", "q": "「white-space: nowrap」の説明として、適切なものはどれか。", "c": ["連続した空白を、そのまま表示する", "テキストを折り返さず、1行で表示する", "単語の途中でも折り返す", "テキストを、すべて非表示にする"], "k": 1, "e": "nowrap は、折り返しをしません。pre は、空白と改行をそのまま表示します。"}, {"t": "word-break", "q": "「word-break: break-all」の説明として、適切なものはどれか。", "c": ["すべての改行を取り除く", "単語の途中では、決して折り返さない", "文字を、すべて1行に詰める", "単語の途中でも、折り返してよい"], "k": 3, "e": "break-all は、はみ出しそうなときに、単語の途中でも折り返します。長いURLなどがはみ出すのを防げます。"}, {"t": "list-style-type", "q": "リストの先頭の記号(マーカー)を、表示しないようにする指定はどれか。", "c": ["list-style-type: hidden", "list-style-type: none", "list-style-type: disc", "list-style-position: none"], "k": 1, "e": "none でマーカーを消せます。disc は黒丸、decimal は数字の連番です。"}, {"t": "カウンター", "q": "CSSカウンターで、値を1ずつ増やすプロパティはどれか。", "c": ["counter-increment", "counter-reset", "content", "list-style"], "k": 0, "e": "counter-reset で初期化し、counter-increment で増やし、content: counter(名前) で表示します。"}, {"t": "border-collapse", "q": "表で、隣り合うセルの枠線を、1本にまとめて表示する指定はどれか。", "c": ["border-collapse: separate", "border-collapse: collapse", "border-spacing: 0", "empty-cells: hide"], "k": 1, "e": "collapse で、隣り合う枠線が重なって1本になります。separate は、枠線を別々に表示します(初期値)。"}, {"t": "empty-cells", "q": "「empty-cells: hide」の説明として、適切なものはどれか。", "c": ["表の、内容が空のセルの枠線や背景を、表示しない", "表の、空の行を削除する", "表の、すべてのセルを非表示にする", "表の、文字を非表示にする"], "k": 0, "e": "empty-cells は、空のセルの枠線と背景を表示するかどうかを指定します(border-collapse: separate のときに有効です)。"}, {"t": "translate", "q": "「transform: translate(10px, 20px)」の説明として、適切なものはどれか。", "c": ["横に10倍、縦に20倍に拡大する", "右へ20px、下へ10px移動する", "10度、20度回転する", "右へ10px、下へ20px移動する"], "k": 3, "e": "translate(x, y) は、移動です。"}, {"t": "scale", "q": "「transform: scale(2)」の説明として、適切なものはどれか。", "c": ["要素を、縦横2倍に拡大する", "要素を、2px移動する", "要素を、2度回転する", "要素を、2倍に傾ける"], "k": 0, "e": "scale は、拡大・縮小です。1より小さいと縮小します。"}, {"t": "transform-origin", "q": "要素の変形(回転や拡大)の、基準となる点を指定するプロパティはどれか。", "c": ["transition-origin", "perspective", "transform-style", "transform-origin"], "k": 3, "e": "transform-origin の初期値は、要素の中心(50% 50%)です。"}, {"t": "transition-timing-function", "q": "トランジションの、変化の速さ(だんだん速く、だんだん遅く、など)を指定するプロパティはどれか。", "c": ["transition-timing-function", "transition-property", "transition-duration", "transition-delay"], "k": 0, "e": "transition-duration は変化にかける時間、transition-delay は開始までの待ち時間、transition-property は対象のプロパティです。"}, {"t": "@keyframes", "q": "CSSアニメーションの、各段階(開始から終了まで)のスタイルを定義する規則はどれか。", "c": ["@keyframes", "@font-face", "@media", "@import"], "k": 0, "e": "@keyframes で名前を付けて段階を定義し、animation-name でその名前を要素に指定します。"}, {"t": "animation-fill-mode", "q": "アニメーションが終わったあとも、最後のキーフレームの状態を保つための指定はどれか。", "c": ["animation-play-state: paused", "animation-fill-mode: forwards", "animation-direction: reverse", "animation-fill-mode: backwards"], "k": 1, "e": "forwards は、終了後も最後の状態を保ちます。backwards は、開始前(遅延中)に、最初のキーフレームの状態を適用します。"}, {"t": "animation-direction", "q": "アニメーションを、往復(順方向と逆方向を交互に)させる指定はどれか。", "c": ["animation-direction: alternate", "animation-direction: normal", "animation-iteration-count: alternate", "animation-fill-mode: alternate"], "k": 0, "e": "alternate は、繰り返しのたびに、再生の向きを交互に反転します。reverse は、逆方向に再生します。"}, {"t": "animation-play-state", "q": "アニメーションを、一時停止させる指定はどれか。", "c": ["animation-play-state: paused", "animation-iteration-count: 0", "animation-play-state: stopped", "animation-fill-mode: none"], "k": 0, "e": "paused で一時停止し、running で再開します。"}, {"t": "column-rule", "q": "段組み(マルチカラム)で、段と段の間に線を引くプロパティはどれか。", "c": ["column-gap", "column-span", "column-width", "column-rule"], "k": 3, "e": "column-rule は、段の間の線です。column-gap は段の間隔、column-span: all は、要素を全段にまたがせます。"}, {"t": "詳細度の比較", "q": "次の2つのセレクタを比べたとき、詳細度が高いのはどれか。\nA: .menu .item\nB: ul li a", "c": ["書いた順で決まり、詳細度は比べられない", "A(クラスセレクタ2つ)", "同じ", "B(タイプセレクタ3つ)"], "k": 1, "e": "詳細度は、IDセレクタ、クラス・属性・疑似クラス、タイプ・疑似要素の順に、数が多いほうが強くなります。Aはクラス2つ、Bはタイプ3つなので、Aのほうが強いです。"}, {"t": "同じ詳細度", "q": "同じ要素に、同じ詳細度のセレクタが複数合致して、同じプロパティを指定しているとき、適用されるのはどれか。", "c": ["指定した値が大きいほうの宣言", "あとから書いたほうの宣言", "どちらも適用されない", "先に書いたほうの宣言"], "k": 1, "e": "詳細度も重要度も同じ場合は、あとに書かれた宣言が優先されます。"}, {"t": "継承", "q": "親要素に指定すると、子孫要素にも引き継がれる(継承される)プロパティはどれか。", "c": ["margin", "border", "color", "background-color"], "k": 2, "e": "文字に関する color や font-size などは、継承されます。margin、border、padding、background などのボックスに関するプロパティは、継承されません。"}, {"t": "セレクタとスタイル", "q": "ul要素の直接の子であるli要素のうち、最初のものだけを、文字の色を赤(red)にするCSSを記述しなさい。ただし、セレクタは ul と li を使い、子結合子と疑似クラスを使うこと。", "code": "ul > li:first-child {\n  color: red;\n}", "e": "子結合子(>)で直接の子に限定し、:first-child で最初の子を選びます。ul > li:nth-child(1) と書いても正解です。", "m": 3}, {"t": "Flexboxの記述", "q": "クラス box の要素の子要素を、横に並べ、水平方向と垂直方向の中央に揃える、display: flex を使ったCSSを記述しなさい。", "code": ".box {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}", "e": "display: flex でflexコンテナにし、justify-content で水平方向(主軸)、align-items で垂直方向(交差軸)を中央にします。", "m": 3}, {"t": "@keyframesの記述", "q": "背景色を赤から青に1秒かけて変えるアニメーション change(@keyframes で定義)を作り、クラス box の要素に1秒、1回だけ再生されるように指定するCSSを記述しなさい。", "code": "@keyframes change {\n  from { background-color: red; }\n  to { background-color: blue; }\n}\n.box {\n  animation: change 1s;\n}", "e": "@keyframes に from と to(または 0% と 100%)を書き、animation に名前と時間を指定します。回数を指定しないときは、1回だけ再生されます。animation-name と animation-duration に分けて書いても正解です。", "m": 3}], "ut": true, "lvn": "公式の出題範囲 1.2(レベル1 Ver2.5)"},
{"id": "l1c", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "要素(セマンティクス・メディア・インタラクティブ)(1/3)", "dm": 1.5, "ps": [{"t": "article要素", "q": "それだけで完結し、単独で配信や再利用ができるコンテンツ(ブログの記事やニュースの記事など)を表す要素はどれか。", "c": ["section", "article", "aside", "div"], "k": 1, "e": "article要素は、独立して完結したコンテンツを表します。section は見出しを伴うテーマごとのまとまり、aside は主な内容から外れた補足、div は特別な意味を持たないまとまりです。"}, {"t": "section要素", "q": "section要素の使い方として、適切なものはどれか。", "c": ["スタイルを付けるためだけのまとまりに使う", "画像とキャプションのまとまりに使う", "見出しを伴う、テーマごとのまとまりに使う", "ページのフッターに使う"], "k": 2, "e": "section要素は、テーマごとのまとまりで、ふつうは見出しを伴います。スタイルを付けるためだけなら div、フッターは footer、画像とキャプションは figure と figcaption を使います。"}, {"t": "ルビ", "q": "「<ruby>漢字<rt>かんじ</rt></ruby>」の rt要素の役割はどれか。", "c": ["ルビ(ふりがな)のテキストを表す", "ルビに対応していないブラウザで表示する括弧を表す", "ルビを付ける元の文字を表す", "ルビの位置を指定する"], "k": 0, "e": "rt要素がルビのテキストです。ルビに対応していないブラウザで、読みを括弧で囲んで表示するには、rp要素を使います。"}, {"t": "挿入と削除", "q": "文書から削除された部分であることを表す要素はどれか。", "c": ["small", "del", "ins", "s"], "k": 1, "e": "del要素は、文書から削除された部分を表します。ins要素は追加された部分です。s要素は「もう正確でない、関係がない」内容、small要素は注記や細目を表します。"}, {"t": "strong要素", "q": "内容の重要性・深刻さ・緊急性が高いことを表す要素はどれか。", "c": ["b", "strong", "em", "i"], "k": 1, "e": "strong要素は、重要性・深刻さ・緊急性を表します。em要素は、文の中で強く読む部分(強勢)を表します。b は、特別な重要性を加えずに注意を引くための部分(キーワードや製品名など)、i は、異なる声や調子のテキスト(術語、外国語の語句、思考など)を表します。"}, {"t": "説明リスト", "q": "用語とその説明を組にして並べるときに使う要素の組合せはどれか。", "c": ["ul・li", "table・tr・td", "dl・dt・dd", "ol・li"], "k": 2, "e": "説明リストは dl要素で囲み、dt要素に用語、dd要素に説明を書きます。ul は順序のないリスト、ol は順序のあるリストです。"}, {"t": "表の見出し", "q": "表(table)全体のタイトル(キャプション)を表す要素はどれか。", "c": ["th", "caption", "title", "thead"], "k": 1, "e": "caption要素は、表のキャプションで、table要素の最初の子として書きます。th は見出しのセル、thead は見出しの行のまとまりです。"}, {"t": "セルの結合", "q": "表で、セルを縦方向(下の行)に結合する属性はどれか。", "c": ["span", "rowspan", "colspan", "merge"], "k": 1, "e": "rowspan は行をまたいで縦に結合し、colspan は列をまたいで横に結合します。どちらも th要素や td要素に指定します。"}, {"t": "poster属性", "q": "video要素の poster属性の役割はどれか。", "c": ["動画を繰り返し再生する", "動画を自動で再生する", "再生・停止などのコントロールを表示する", "動画を再生する前に表示する画像を指定する"], "k": 3, "e": "poster は、再生前に表示する画像です。自動再生は autoplay、繰り返しは loop、コントロールの表示は controls です。"}, {"t": "字幕", "q": "video要素に、WebVTT形式の字幕ファイルを付けるときに使う要素はどれか。", "c": ["caption", "subtitle", "track", "source"], "k": 2, "e": "track要素を video の中に書き、src に字幕ファイル(.vtt)、kind=\"subtitles\" などで種類を指定します。source要素は、動画ファイルそのものを複数の形式で指定するときに使います。"}, {"t": "source要素", "q": "video要素の中に、複数の source要素を書く目的として適切なものはどれか。", "c": ["動画の再生前に表示する画像を指定する", "動画に字幕を付ける", "複数の形式の動画を用意して、ブラウザが再生できるものを使えるようにする", "複数の動画を、同時に並べて再生する"], "k": 2, "e": "ブラウザによって再生できる形式(コンテナやコーデック)が違うため、source要素で複数の候補を書きます。ブラウザは、上から順に再生できるものを選びます。"}, {"t": "新しいタブで開く", "q": "リンク先を、新しいタブ(新しいウィンドウ)で開くための、a要素の属性の指定はどれか。", "c": ["target=\"_self\"", "target=\"_blank\"", "href=\"_blank\"", "rel=\"new\""], "k": 1, "e": "target=\"_blank\" で、新しい閲覧コンテキスト(タブやウィンドウ)で開きます。_self は同じ場所で開きます(初期値)。"}, {"t": "details要素", "q": "クリックで内容の表示・非表示を切り替えられる部品(ディスクロージャーウィジェット)を作るとき、details要素の中で、見出し(常に表示される部分)に使う要素はどれか。", "c": ["legend", "header", "caption", "summary"], "k": 3, "e": "details要素の最初の子に summary要素を書くと、その内容が見出しになり、クリックで残りの内容を開いたり閉じたりできます。open属性を付けると、最初から開いた状態になります。"}, {"t": "メールアドレスの入力欄", "q": "メールアドレスを入力させる入力欄を作る、input要素の type属性の値はどれか。", "c": ["email", "mail", "address", "text-mail"], "k": 0, "e": "type=\"email\" にすると、ブラウザがメールアドレスの形式かどうかを確かめます。電話番号は tel、URLは url です。"}, {"t": "iframe要素", "q": "ページの中に、別のHTML文書を入れ子の閲覧コンテキストとして埋め込むための、最も一般的な要素はどれか。", "c": ["embed", "frameset", "iframe", "object"], "k": 2, "e": "iframe要素は、別のHTML文書を入れ子の閲覧コンテキストとして埋め込みます。frameset はHTML5では廃止された要素です。object や embed でもHTMLを表示できますが、主に外部リソース用です。"}, {"t": "動画の記述", "q": "動画ファイル movie.mp4 を、再生・停止などのコントロールを表示して埋め込むHTMLを記述しなさい。", "code": "<video src=\"movie.mp4\" controls></video>", "e": "video要素の src に動画ファイル、controls 属性でコントロールを表示します。中に <source src=\"movie.mp4\" type=\"video/mp4\"> を書く方法でも正解です。", "m": 3}, {"t": "nav要素", "q": "ページ内の、主要なナビゲーションリンクのまとまりを表す要素はどれか。", "c": ["aside", "address", "nav", "header"], "k": 2, "e": "nav要素は、主要なナビゲーションのまとまりです。すべてのリンクを入れるのではなく、メニューなどの主要なものに使います。"}, {"t": "aside要素", "q": "主な内容とは直接の関係が薄い、補足的な内容(サイドバーや関連記事など)を表す要素はどれか。", "c": ["article", "section", "aside", "nav"], "k": 2, "e": "aside要素は、周りの内容と、間接的にしか関係しない内容を表します。"}, {"t": "address要素", "q": "address要素の用途として、適切なものはどれか。", "c": ["メールの宛先を表す", "ネットワークのIPアドレスを表す", "どんな住所でも、住所であれば表す", "最も近い祖先のarticle要素、またはbody要素の、連絡先情報を表す"], "k": 3, "e": "address要素は、その文書(または記事)の著者などの、連絡先を表します。関係のない住所の表記には使いません。"}, {"t": "q要素", "q": "文中の短い引用を表し、多くのブラウザが引用符を自動で付ける要素はどれか。", "c": ["blockquote", "q", "abbr", "cite"], "k": 1, "e": "q要素は、インラインの短い引用です。段落のような長い引用は、blockquote要素を使います。"}, {"t": "cite要素", "q": "cite要素が表すものとして、適切なものはどれか。", "c": ["引用した人の名前", "引用元のURL", "引用した文章そのもの", "参照している作品(書籍、論文、映画など)のタイトル"], "k": 3, "e": "cite要素は、作品のタイトルを表します。HTML標準では、人の名前を表す用途には使いません。"}, {"t": "abbr要素", "q": "略語を表し、title属性で正式名称を示せる要素はどれか。", "c": ["dfn", "cite", "small", "abbr"], "k": 3, "e": "abbr要素は略語で、<abbr title=\"HyperText Markup Language\">HTML</abbr> のように使います。dfn要素は、その場で定義する用語です。"}], "ut": true, "lvn": "公式の出題範囲 1.3(レベル1 Ver2.5)"},
{"id": "l1c2", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "要素(セマンティクス・メディア・インタラクティブ)(2/3)", "dm": 1.5, "ps": [{"t": "samp要素", "q": "プログラムが出力する結果(出力例)を表す要素はどれか。", "c": ["samp", "kbd", "var", "code"], "k": 0, "e": "samp は出力例、kbd はキーボードなどからの入力、var は変数、code はコンピュータのコードを表します。"}, {"t": "pre要素", "q": "ソースコードなどを、空白や改行をそのまま保って表示する要素はどれか。", "c": ["code", "samp", "pre", "p"], "k": 2, "e": "pre要素は、整形済みのテキストを表し、空白と改行がそのまま表示されます。code要素は、コードであることの意味を表すだけで、改行は保ちません。"}, {"t": "time要素", "q": "日付や時刻を、機械が読める形(datetime属性)で表す要素はどれか。", "c": ["datetime", "calendar", "date", "time"], "k": 3, "e": "time要素は、<time datetime=\"2026-11-13\">2026年11月13日</time> のように使います。date、datetime、calendar という要素はありません。"}, {"t": "mark要素", "q": "文脈での関連性を示すために、検索語に該当する部分などを目立たせる(ハイライトする)要素はどれか。", "c": ["small", "mark", "strong", "em"], "k": 1, "e": "mark要素は、利用者の関心に関連する部分を、目立たせます。strong は重要性、em は強勢を表します。"}, {"t": "hr要素", "q": "hr要素が表すものとして、適切なものはどれか。", "c": ["ページの先頭へ戻るリンク", "段落レベルの、主題の区切り(多くのブラウザで水平線として表示される)", "文書全体の終わり", "文字の取り消し線"], "k": 1, "e": "hr要素は、主題の切れ目を表します。見た目の線を引くだけのものではなく、CSSで見た目を変えられます。"}, {"t": "wbr要素", "q": "wbr要素の説明として、適切なものはどれか。", "c": ["改行を禁止する", "必ず改行する", "単語の途中で、改行してもよい位置を示す", "段落を区切る"], "k": 2, "e": "wbr要素は、長い単語やURLの中で、改行してよい位置を示します。必ず改行するのは、br要素です。"}, {"t": "olの属性", "q": "ol要素で、番号を5から始めるための記述はどれか。", "c": ["<ol start=\"5\">", "<ol from=\"5\">", "<ol begin=\"5\">", "<ol first=\"5\">"], "k": 0, "e": "ol要素の start属性で、開始番号を指定します。reversed属性を付けると、番号が降順になります。"}, {"t": "th要素のscope", "q": "<th scope=\"col\"> の説明として、適切なものはどれか。", "c": ["そのセルの幅を、列の幅に合わせる", "そのセルが、列全体に結合されることを示す", "その見出しセルが、同じ列のセルの見出しであることを示す", "そのセルの文字を、縦書きにする"], "k": 2, "e": "scope属性は、見出しセルの対象を示します。col は列、row は行です。"}, {"t": "colgroup要素", "q": "表の列を、まとめてスタイル付けするために使う要素の組合せはどれか。", "c": ["tr と td", "colgroup と col", "thead と tbody", "caption と summary"], "k": 1, "e": "colgroup要素の中に col要素を書いて、列にスタイルを付けます。thead と tbody は、行のグループです。"}, {"t": "figure要素", "q": "図表や写真と、そのキャプションをまとめる要素の組合せはどれか。", "c": ["image と label", "picture と legend", "fig と caption", "figure と figcaption"], "k": 3, "e": "figure要素の中に、図表を置き、figcaption要素でキャプションを付けます。"}, {"t": "lang属性の部分指定", "q": "日本語の文書の中の、一部の英語の語句を、英語であると示す書き方として、適切なものはどれか。", "c": ["<span charset=\"en\">Hello</span>", "<span lang=\"en\">Hello</span>", "<span language=\"english\">Hello</span>", "<span locale=\"en\">Hello</span>"], "k": 1, "e": "lang属性は、どの要素にも指定できます。読み上げソフトが、正しい発音で読むために役立ちます。"}, {"t": "dir属性", "q": "dir属性に rtl を指定したときの意味として、適切なものはどれか。", "c": ["要素が、行の先頭から表示される", "要素が、右に寄る", "文字の方向が、右から左になる", "文字の方向が、上から下になる"], "k": 2, "e": "dir=\"rtl\" は right-to-left で、アラビア語などの、右から左へ書く言語に使います。ltr は左から右です。"}, {"t": "download属性", "q": "a要素の download属性の説明として、適切なものはどれか。", "c": ["リンク先の、ファイルサイズを表示する", "リンク先が、ダウンロードできないことを示す", "リンク先を、新しいタブで開く", "リンク先を開く代わりに、ダウンロードするように指示する"], "k": 3, "e": "download属性があると、ブラウザは、リンク先をダウンロードして保存します。ファイル名の指定もできます。"}, {"t": "rel=noopener", "q": "<a href=\"…\" target=\"_blank\" rel=\"noopener\"> の rel=\"noopener\" の目的として、適切なものはどれか。", "c": ["リンク先のページの内容を、検索エンジンに登録させない", "開いた先のページが、window.opener を使って、元のページを操作できないようにする", "リンク先のページを、キャッシュさせない", "リンクを、クリックできなくする"], "k": 1, "e": "noopener は、新しいページが、開いた元のページを、window.opener で操作するのを防ぎます。検索エンジンへの指示ではありません。"}, {"t": "ページ内リンク", "q": "同じページの中の、id=\"section1\" が付いた要素の位置へ移動するリンクの書き方はどれか。", "c": ["<a href=\"id:section1\">", "<a href=\"section1\">", "<a href=\"#section1\">", "<a name=\"#section1\">"], "k": 2, "e": "href=\"#id名\" で、そのidを持つ要素の位置に移動します。"}, {"t": "mailto", "q": "クリックしたときに、メールの作成画面を開く、a要素のhref属性の書き方はどれか。", "c": ["mailto:info@example.com", "email:info@example.com", "tel:info@example.com", "mail://info@example.com"], "k": 0, "e": "mailto: スキームで、メールアドレスを指定します。tel: は電話番号です。"}, {"t": "enctype", "q": "フォームでファイルをアップロードするとき、form要素に指定する、正しい組合せはどれか。", "c": ["method=\"get\" と enctype=\"multipart/form-data\"", "method=\"post\" と enctype=\"multipart/form-data\"", "method=\"put\" と enctype=\"image/*\"", "method=\"post\" と enctype=\"text/plain\""], "k": 1, "e": "ファイルを送るときは、POSTで、enctype を multipart/form-data にします。GETではファイルを送れません。"}, {"t": "readonlyとdisabled", "q": "フォームの入力欄で、readonly属性とdisabled属性の違いとして、正しいものはどれか。", "c": ["readonlyの値は送信されるが、disabledの値は送信されない", "readonlyの値は送信されないが、disabledの値は送信される", "どちらも、値は送信されない", "どちらも、値は送信される"], "k": 0, "e": "readonlyは、編集できないだけで、フォームを送信すると値も送られます。disabledは、操作できず、フォームを送信しても値は送られません。"}, {"t": "placeholder", "q": "入力欄に、入力例などのヒントを、薄い文字で表示する属性はどれか。", "c": ["alt", "value", "title", "placeholder"], "k": 3, "e": "placeholder属性は、入力欄が空のときだけ、ヒントを表示します。value は、入力欄の初期値です。"}, {"t": "autocomplete", "q": "入力欄で、ブラウザによる入力の自動補完を無効にするための指定はどれか。", "c": ["autocomplete=\"off\"", "complete=\"off\"", "autofill=\"none\"", "autocomplete=\"false\""], "k": 0, "e": "autocomplete属性に off を指定すると、自動補完が無効になります。"}, {"t": "ラジオボタンのグループ", "q": "ラジオボタンを、1つのグループにして、どれか1つしか選べないようにするには、どうすればよいか。", "c": ["form要素を、ラジオボタンごとに分ける", "同じグループのすべてに、同じ name属性を付ける", "同じグループのすべてに、同じ id属性を付ける", "同じグループのすべてに、同じ value属性を付ける"], "k": 1, "e": "ラジオボタンは、name属性が同じものが、1つのグループです。idは、文書内で一意でなければなりません。"}, {"t": "type=\"number\"", "q": "数値を入力させ、最小値を0、最大値を100にする、input要素の書き方はどれか。", "c": ["<input type=\"text\" range=\"0-100\">", "<input type=\"number\" from=\"0\" to=\"100\">", "<input type=\"number\" min=\"0\" max=\"100\">", "<input type=\"number\" low=\"0\" high=\"100\">"], "k": 2, "e": "type=\"number\" に、min と max を指定します。step属性で、刻みも指定できます。"}], "ut": true, "lvn": "公式の出題範囲 1.3(レベル1 Ver2.5)"},
{"id": "l1c3", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "要素(セマンティクス・メディア・インタラクティブ)(3/3)", "dm": 1.5, "ps": [{"t": "type=\"range\"", "q": "スライダーで値を選ぶ入力欄を作る、input要素の type属性の値はどれか。", "c": ["scale", "range", "bar", "slider"], "k": 1, "e": "type=\"range\" は、min、max、step と組み合わせて、スライダーを作ります。"}, {"t": "type=\"hidden\"", "q": "画面には表示せず、フォームと一緒にサーバに送る値を持たせる、input要素の type属性の値はどれか。", "c": ["none", "hidden", "invisible", "secret"], "k": 1, "e": "type=\"hidden\" は、画面に表示されず、name と value が送信されます。"}, {"t": "type=\"file\"", "q": "複数のファイルを、同時に選べるようにする、input要素の書き方はどれか。", "c": ["<input type=\"files\">", "<input type=\"file\" multiple>", "<input type=\"file\" count=\"2\">", "<input type=\"file\" many>"], "k": 1, "e": "type=\"file\" に multiple属性を付けると、複数のファイルを選べます。"}, {"t": "label要素", "q": "label要素を、クリックしたときの動作として、適切なものはどれか。", "c": ["入力欄が、非表示になる", "関連付けられた入力欄が、フォーカスされる(チェックボックスなら、状態が切り替わる)", "入力欄が、削除される", "入力欄の内容が、送信される"], "k": 1, "e": "label要素は、for属性か、入力欄を囲むことで、入力欄と関連付けます。クリックできる範囲が広がり、使いやすくなります。"}, {"t": "datalist要素", "q": "入力欄に、候補を示しながら、候補以外の自由な入力もできるようにする、要素と属性の組合せはどれか。", "c": ["optgroup要素と、input要素の form属性", "select要素と、input要素の multiple属性", "datalist要素と、input要素の list属性", "fieldset要素と、input要素の pattern属性"], "k": 2, "e": "input要素の list属性に、datalist要素のidを指定します。select要素は、候補からしか選べません。"}, {"t": "fieldset要素", "q": "関連するフォーム部品をグループにまとめ、見出しを付ける要素の組合せはどれか。", "c": ["group と title", "fieldset と legend", "section と label", "form と caption"], "k": 1, "e": "fieldset要素でグループにして、最初の子の legend要素で、見出しを付けます。"}, {"t": "buttonのtype", "q": "form要素の中にある <button>送信</button> で、type属性を省略したときの動作として、正しいものはどれか。", "c": ["ページを再読み込みする", "フォームの内容を、リセットする", "フォームを送信する(type=\"submit\" と同じ)", "何も起こらない(type=\"button\" と同じ)"], "k": 2, "e": "form に関連付けられた button要素では、type を省略したときの動作は submit です。送信させたくないときは、type=\"button\" を指定します。"}, {"t": "progress要素", "q": "作業の進み具合(たとえばダウンロードの進行)を表す要素はどれか。", "c": ["range", "meter", "output", "progress"], "k": 3, "e": "progress要素は、作業の進捗を value と max で表します。meter要素は、残りの容量のような、範囲内の量を表します。"}, {"t": "sandbox属性", "q": "iframe要素の sandbox属性の説明として、適切なものはどれか。", "c": ["埋め込んだ文書の、大きさを自動で合わせる", "埋め込んだ文書に対して、スクリプトの実行などの機能を制限する", "埋め込んだ文書を、キャッシュに保存する", "埋め込んだ文書を、砂のようにぼかして表示する"], "k": 1, "e": "sandbox属性を付けると、フォームの送信やスクリプトの実行などが、制限されます。allow-scripts などの値で、一部の機能だけを許可します。"}, {"t": "map要素", "q": "画像の一部分を、リンクにする(イメージマップ)ときに使う要素の組合せはどれか。", "c": ["picture と source", "map と area", "figure と a", "canvas と path"], "k": 1, "e": "img要素の usemap属性で、map要素を指定し、map の中の area要素で、リンクの領域を定義します。"}, {"t": "コンテナとコーデック", "q": "動画や音声のファイルについて、コンテナとコーデックの違いとして、適切なものはどれか。", "c": ["コンテナは音声だけを、コーデックは映像だけを扱う", "コンテナは、映像や音声などをまとめて1つのファイルに格納する形式で、コーデックは、映像や音声を符号化する方式", "コンテナは、映像を符号化する方式で、コーデックは、ファイルの形式", "コンテナとコーデックは、同じ意味で使われる"], "k": 1, "e": "MP4やWebMはコンテナ、H.264やVP9は映像コーデック、AACやOpusは音声コーデックです。"}, {"t": "音声コーデック", "q": "次のうち、音声のコーデックはどれか。", "c": ["AAC", "WebM", "VP9", "H.264"], "k": 0, "e": "AACは音声のコーデックです。H.264とVP9は映像のコーデック、WebMはコンテナです。"}, {"t": "映像コーデック", "q": "次のうち、映像のコーデックはどれか。", "c": ["MP3", "AAC", "MP4", "H.264"], "k": 3, "e": "H.264(AVC)は映像のコーデックです。AACとMP3は音声のコーデック(MP3は音声のファイル形式でもあります)、MP4はコンテナです。"}, {"t": "trackのkind", "q": "track要素で、聴覚に障害がある人のために、台詞のほか効果音などの情報も含めた字幕を指定する kind属性の値はどれか。", "c": ["subtitles", "chapters", "descriptions", "captions"], "k": 3, "e": "captions は、効果音なども含めた字幕です。subtitles は、台詞の翻訳などの字幕、chapters は章の区切り、descriptions は、映像の内容の説明です。"}, {"t": "WebVTT", "q": "字幕のファイル形式であるWebVTTで、ファイルの先頭に書く文字列はどれか。", "c": ["WEBVTT", "<?vtt?>", "#VTT", "SUBTITLES"], "k": 0, "e": "WebVTTファイルは、先頭の行に WEBVTT と書きます。続いて、開始時刻 --> 終了時刻 と字幕の文を書きます。"}, {"t": "muted属性", "q": "video要素の muted属性の説明として、適切なものはどれか。", "c": ["動画を、白黒で表示する", "音声を消した(ミュートの)状態で、再生を始める", "動画の、ダウンロードを禁止する", "動画を、自動で再生する"], "k": 1, "e": "muted は、音を消した状態にします。多くのブラウザでは、ミュートの動画は、自動再生(autoplay)が許可されやすくなっています。"}, {"t": "preload属性", "q": "video要素の preload=\"none\" の説明として、適切なものはどれか。", "c": ["動画を、キャッシュに保存しない", "動画を、再生しない", "再生が始まるまで、動画のデータを先読みしない", "動画の、最初の1枚の画像を表示しない"], "k": 2, "e": "preload は、先読みのヒントです。none は先読みしない、metadata はメタ情報だけ、auto は必要なら全体を先読みします。"}, {"t": "フォームの記述", "q": "「性別」という見出し(fieldsetの中のlegend)の下に、name が gender の2つのラジオボタン(値は m と f、ラベルは「男」「女」)を、label要素で囲んで記述しなさい。", "code": "<fieldset>\n  <legend>性別</legend>\n  <label><input type=\"radio\" name=\"gender\" value=\"m\">男</label>\n  <label><input type=\"radio\" name=\"gender\" value=\"f\">女</label>\n</fieldset>", "e": "ラジオボタンは、name属性を同じにしてグループにします。label で囲むと、ラベルの文字もクリックできます。for と id で関連付ける書き方でも正解です。", "m": 3}, {"t": "表の記述", "q": "表のキャプションを「売上」、見出しの行にth要素で「月」「金額」の2つ、データの行に td要素で「1月」「100」の2つを持つ、table要素を記述しなさい。thead と tbody も使うこと。", "code": "<table>\n  <caption>売上</caption>\n  <thead>\n    <tr><th>月</th><th>金額</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>1月</td><td>100</td></tr>\n  </tbody>\n</table>", "e": "caption は table の最初の子として書きます。見出しの行は thead、データは tbody に入れます。th に scope=\"col\" を付けても正解です。", "m": 3}, {"t": "字幕付きの動画", "q": "動画ファイル movie.mp4 を、controls付きで埋め込み、日本語(ja)の字幕ファイル sub.vtt を、subtitles として指定する、HTMLを記述しなさい。", "code": "<video src=\"movie.mp4\" controls>\n  <track kind=\"subtitles\" src=\"sub.vtt\" srclang=\"ja\" label=\"日本語\">\n</video>", "e": "track要素に、kind、src、srclang を指定します。label は、字幕を選ぶメニューに表示される名前です。source要素を使って動画を指定する書き方でも正解です。", "m": 3}], "ut": true, "lvn": "公式の出題範囲 1.3(レベル1 Ver2.5)"},
{"id": "l1d", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "レスポンシブWebデザイン(マルチデバイス・メディアクエリ)(1/2)", "dm": 1.5, "ps": [{"t": "viewport", "q": "スマートフォンで、ページの幅を端末の画面の幅に合わせ、最初の拡大率を等倍にする指定はどれか。", "c": ["<link rel=\"viewport\" href=\"device-width\">", "<meta charset=\"device-width\">", "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">", "<meta name=\"screen\" content=\"width=100%\">"], "k": 2, "e": "meta要素の name=\"viewport\" で、表示領域を指定します。width=device-width で端末の幅に合わせ、initial-scale=1 で最初の拡大率を1倍にします。"}, {"t": "max-width", "q": "次のCSSが適用されるのはどれか。\n\n@media (max-width: 600px) {\n  body { font-size: 14px; }\n}", "c": ["画面の幅が600pxより大きいとき", "画面(ビューポート)の幅が600px以下のとき", "画面の幅がちょうど600pxのときだけ", "印刷するときだけ"], "k": 1, "e": "max-width: 600px は「幅が600px以下」の条件です。600px以上なら min-width: 600px と書きます。"}, {"t": "min-width", "q": "「@media (min-width: 768px) { ... }」が適用される条件はどれか。", "c": ["ビューポートの幅が768px以上", "ビューポートの幅が768px以下", "ビューポートの高さが768px以上", "画面の解像度が768dpi以上"], "k": 0, "e": "min-width は「最小の幅」なので、768px以上のときに適用されます。スマートフォン向けのスタイルを先に書き、広い画面向けを min-width で追加する書き方は、モバイルファーストと呼ばれます。"}, {"t": "メディアタイプ", "q": "印刷するときだけ適用するスタイルを書く指定はどれか。", "c": ["@media paper { ... }", "@media screen { ... }", "@media all { ... }", "@media print { ... }"], "k": 3, "e": "メディアタイプ print は、印刷(印刷プレビューを含む)のときに適用されます。screen は画面、all はすべての機器です。"}, {"t": "画面の向き", "q": "「@media (orientation: landscape) { ... }」が適用されるのはどれか。", "c": ["画面が高解像度のとき", "ビューポートが横長(幅が高さより大きい)のとき", "端末を振ったとき", "ビューポートが縦長のとき"], "k": 1, "e": "orientation は画面の向きのメディア特性で、landscape は横長(幅が高さより大きい)、portrait は縦長(高さが幅以上。幅と高さが等しい場合も portrait)です。"}, {"t": "メディアクエリの記述", "q": "ビューポートの幅が600px以下のとき、クラス side の要素を表示しない(場所も詰める)ようにするCSSを記述しなさい。", "code": "@media (max-width: 600px) {\n  .side {\n    display: none;\n  }\n}", "e": "max-width: 600px で600px以下の条件にし、その中に display: none を書きます。@media screen and (max-width: 600px) と書いても正解です。", "m": 3}, {"t": "フルードイメージ", "q": "「img { max-width: 100%; height: auto; }」の効果として、適切なものはどれか。", "c": ["画像が、親要素の幅より大きく表示されず、縦横の比率を保ったまま縮む", "画像が、元の大きさより小さくならない", "画像の高さが0になって見えなくなる", "画像が、常に画面いっぱいに引き伸ばされる"], "k": 0, "e": "max-width: 100% で、親要素の幅を超えないようにし、height: auto で縦横の比率を保ちます。これをフルードイメージといいます。"}, {"t": "フルードグリッド", "q": "フルードグリッドの説明として、適切なものはどれか。", "c": ["すべての段の幅をpxで固定するレイアウト", "ブラウザごとの初期スタイルの違いをなくす手法", "段の幅を%などの相対的な値で指定して、画面の幅に合わせて伸び縮みさせるレイアウト", "画像を1枚にまとめて、表示する部分を切り替える手法"], "k": 2, "e": "フルードグリッドは、幅を相対値で指定する可変レイアウトです。画像を1枚にまとめるのはCSSスプライト、初期スタイルの違いをなくすのはリセットCSSです。"}, {"t": "CSSスプライト", "q": "CSSスプライトの主な目的として、適切なものはどれか。", "c": ["画像をアニメーションさせる", "画像に代替テキストを付ける", "画像を高画質にする", "複数の小さな画像を1枚にまとめて、画像を取りに行くリクエストの数を減らす"], "k": 3, "e": "CSSスプライトは、複数の画像を1枚にまとめ、background-position で表示する部分を切り替えます。リクエストの数が減るので、表示が速くなります。"}, {"t": "リセットCSS", "q": "リセットCSSの目的として、適切なものはどれか。", "c": ["フォームの入力内容を消す", "ブラウザのキャッシュを消す", "ページのCSSをすべて削除する", "ブラウザごとに異なる初期スタイル(余白など)の違いをなくし、表示をそろえる"], "k": 3, "e": "ブラウザには、要素ごとの初期スタイルがあり、ブラウザによって少しずつ違います。リセットCSSで、余白などをそろえてから、スタイルを書きます。"}, {"t": "電話番号へのリンク", "q": "スマートフォンでタップすると、電話をかけられるリンクの書き方はどれか。", "c": ["<a tel=\"0312345678\">電話する</a>", "<a href=\"phone:0312345678\">電話する</a>", "<a href=\"tel:0312345678\">電話する</a>", "<a href=\"call://0312345678\">電話する</a>"], "k": 2, "e": "href に tel: スキームで電話番号を書きます。メールなら mailto: を使います。"}, {"t": "ホーム画面のアイコン", "q": "iPhoneなどで、Webページをホーム画面に追加したときに表示するアイコンを指定する書き方はどれか。", "c": ["<img rel=\"icon\" src=\"icon.png\">", "<link rel=\"apple-touch-icon\" href=\"icon.png\">", "<link rel=\"stylesheet\" href=\"icon.png\">", "<meta name=\"icon\" content=\"icon.png\">"], "k": 1, "e": "link要素の rel=\"apple-touch-icon\" で、ホーム画面のアイコンを指定します。ブラウザのタブなどに出るファビコンは rel=\"icon\" で指定します。"}, {"t": "deferとasync", "q": "script要素の defer属性の説明として、適切なものはどれか。", "c": ["HTMLの解析を止めずにスクリプトを読み込み、HTMLの解析が終わってから、書いた順に実行する", "スクリプトを、ページを閉じるときに実行する", "スクリプトを読み込み終わったらすぐに実行し、実行の順番は保証されない", "スクリプトを実行しない"], "k": 0, "e": "defer は、解析が終わってから記述順に実行します。async は、読み込みが終わり次第すぐに実行するので、順番は保証されません。通常のスクリプトでは、どちらも src属性を持つ外部スクリプトのときだけ効果があります。"}, {"t": "高解像度の画面", "q": "次のimg要素で、画面のピクセル密度が2倍(2x)の端末に表示されるのはどれか。\n\n<img src=\"logo.png\" srcset=\"logo-2x.png 2x\" alt=\"ロゴ\">", "c": ["logo.png", "両方の画像が並んで表示される", "どちらも表示されない", "logo-2x.png"], "k": 3, "e": "srcset に「画像 2x」と書くと、ピクセル密度が2倍の画面では、通常その画像が選ばれます(どれを選ぶかの最終判断はブラウザに任されます)。対応していないブラウザや、1倍の画面では src の画像が使われます。"}, {"t": "メディアクエリ(範囲)", "q": "「@media screen and (min-width: 600px) and (max-width: 900px) { ... }」が適用される条件として、適切なものはどれか。", "c": ["印刷するときで、幅が600px以上900px以下のとき", "画面で、ビューポートの幅が600px以上900px以下のとき", "画面で、幅が600px以下または900px以上のとき", "画面で、幅がちょうど600pxまたは900pxのとき"], "k": 1, "e": "and は、すべての条件を満たすことを表します。"}, {"t": "メディアクエリ(カンマ)", "q": "「@media (max-width: 600px), print { ... }」が適用される条件として、適切なものはどれか。", "c": ["幅が600px以下のとき、または、印刷するとき", "幅が600px以下で、かつ、印刷するときだけ", "幅が600px以下のときだけ", "印刷するときだけ"], "k": 0, "e": "カンマ(,)は、どれかの条件を満たせばよい「または」を表します。"}, {"t": "解像度の単位", "q": "メディアクエリの解像度の単位で、「2dppx」は何dpiにあたるか(1dppxは96dpi)。", "c": ["144dpi", "384dpi", "96dpi", "192dpi"], "k": 3, "e": "dppx は、1CSSピクセルあたりのドット数です。1dppx=96dpi なので、2dppx=192dpi です。高解像度の画面を判定するのに使います。"}], "ut": true, "lvn": "公式の出題範囲 1.4(レベル1 Ver2.5)"},
{"id": "l1d2", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "レスポンシブWebデザイン(マルチデバイス・メディアクエリ)(2/2)", "dm": 1.5, "ps": [{"t": "無効なメディアクエリ", "q": "メディアクエリに、ブラウザが理解できないメディア特性や、誤った構文を書いたときの動作として、適切なものはどれか。", "c": ["そのクエリは偽として扱われ、その規則は適用されない", "そのクエリは真として扱われ、規則が常に適用される", "エラーが表示されて、ページが読み込まれない", "ページ全体のスタイルシートが、無効になる"], "k": 0, "e": "理解できないメディアクエリは、偽(not all)として扱われます。ほかのスタイルには、影響しません。"}, {"t": "prefers-color-scheme", "q": "「@media (prefers-color-scheme: dark) { ... }」が適用される条件として、適切なものはどれか。", "c": ["画面の明るさが、半分以下のとき", "ページの背景色が、黒のとき", "画面が、暗い場所で使われているとき", "利用者が、OSやブラウザで、ダークテーマ(暗い配色)を希望しているとき"], "k": 3, "e": "prefers-color-scheme は、利用者の配色の好みを表すメディア特性です。"}, {"t": "prefers-reduced-motion", "q": "「@media (prefers-reduced-motion: reduce) { ... }」の用途として、適切なものはどれか。", "c": ["動画の画質を下げる", "ページの読み込みを遅くする", "動きの多いアニメーションを減らしたいという利用者の設定に応じて、アニメーションを控える", "画面の大きさを小さくする"], "k": 2, "e": "OSで、動きを減らす設定にしている利用者に、アニメーションを控えるなど、配慮するために使います。"}, {"t": "vw", "q": "CSSの単位「1vw」は、何を表すか。", "c": ["親要素の幅の1%", "ビューポートの幅の1%", "文字の大きさの1%", "画面の解像度の1%"], "k": 1, "e": "vw はビューポートの幅の1%、vh は高さの1%です。"}, {"t": "rem", "q": "CSSの単位「rem」は、何を基準にした長さか。", "c": ["その要素の幅", "親要素の文字の大きさ", "ルート要素(html要素)の文字の大きさ", "ビューポートの幅"], "k": 2, "e": "rem は、html要素の font-size を基準にします。em は、その要素自身の font-size を基準にします。"}, {"t": "em", "q": "CSSの単位「em」を使った「width: 10em」は、何を基準にした幅か。", "c": ["その要素自身の font-size(文字の大きさ)", "html要素の font-size", "親要素の幅", "ビューポートの幅"], "k": 0, "e": "em は、その要素の font-size を基準にします。font-size プロパティ自身に指定した em は、親要素の font-size が基準になります。"}, {"t": "固定レイアウト", "q": "固定レイアウトと可変レイアウトの違いとして、適切なものはどれか。", "c": ["固定レイアウトは、幅をpxなどで固定し、可変レイアウトは、%などで画面の幅に合わせて伸び縮みさせる", "固定レイアウトは、画面の幅に合わせて伸び縮みし、可変レイアウトは、幅が固定されている", "固定レイアウトは、画像だけに使い、可変レイアウトは、文字だけに使う", "固定レイアウトは、PC用で、可変レイアウトは、スマートフォン用に限られる"], "k": 0, "e": "固定レイアウトは、幅をpxで固定します。可変(リキッド)レイアウトは、幅を%などの相対値で指定して、画面の幅に合わせます。"}, {"t": "ブレークポイント", "q": "レスポンシブWebデザインの、ブレークポイントの説明として、適切なものはどれか。", "c": ["レイアウトを切り替える、画面の幅の境目", "ページを、印刷用に分ける位置", "スクロールを、止める位置", "画像の読み込みを、中断する位置"], "k": 0, "e": "ブレークポイントは、メディアクエリで、レイアウトを切り替える画面の幅の境目です。"}, {"t": "sizes属性", "q": "img要素の srcset属性で、「480w」のように幅を指定したとき、sizes属性の役割として、適切なものはどれか。", "c": ["画像の縦横の大きさを、強制的に変える", "画像の代替テキストを指定する", "画像が表示される幅の見込みを、ブラウザに伝えて、適切な画像を選ばせる", "画像を、圧縮する"], "k": 2, "e": "srcset に画像と幅の組(w記述子)を書き、sizes で表示幅の見込みを伝えると、ブラウザが適切な画像を選びます。"}, {"t": "picture要素", "q": "picture要素の説明として、適切なものはどれか。", "c": ["画像を、背景に表示する", "条件(画面の幅や画像の形式)に応じて、複数の画像から、適切なものを選んで表示する", "画像を、写真として拡大する", "画像に、キャプションを付ける"], "k": 1, "e": "picture要素の中に、source要素を複数書き、最後に img要素を書きます。media属性や type属性で、条件を指定します。"}, {"t": "loading属性", "q": "img要素の loading=\"lazy\" の説明として、適切なものはどれか。", "c": ["画像を、先に読み込む", "画像を、ゆっくり表示する", "画像が画面に近づくまで、読み込みを遅らせる", "画像を、読み込まない"], "k": 2, "e": "lazy は、遅延読み込みです。ページを最初に表示するまでの通信量を減らせます。"}, {"t": "スタンドアローンモード", "q": "Webアプリのマニフェスト(Web App Manifest)で、「display: standalone」を指定したときの動作として、適切なものはどれか。", "c": ["常に、画面全体を暗い配色にする", "ホーム画面などから起動したとき、ブラウザのアドレスバーなどを表示せず、アプリのように表示する", "ネットワークに接続せずに、動作する", "ほかのアプリと、画面を分割する"], "k": 1, "e": "standalone は、ブラウザの操作画面をできるだけ隠し、独立したアプリのように表示します。オフライン動作は、Service Workerの役割です。"}, {"t": "画素密度", "q": "画素密度が2倍の画面で、幅100pxに表示する画像を、くっきり表示するために用意する画像として、適切なものはどれか。", "c": ["横が200px以上の画像", "横が50px以上の画像", "横が100pxちょうどの画像", "横が1000px以上の画像"], "k": 0, "e": "画素密度が2倍の画面では、CSSの1pxが、2×2の物理的なドットで表示されます。くっきり表示するには、表示サイズの2倍の画素数の画像が必要です。"}, {"t": "拡大・縮小の許可", "q": "スマートフォン向けのページで、利用者による拡大・縮小を許可するかどうかについて、アクセシビリティの観点から適切なものはどれか。", "c": ["禁止するほうがよい(表示が崩れるので)", "画面の幅を、必ず320pxに固定するほうがよい", "許可したほうがよい(視力の弱い人などが、拡大して読めるように)", "許可しても禁止しても、アクセシビリティには関係しない"], "k": 2, "e": "viewportの user-scalable=no などで拡大を禁止すると、拡大して読みたい人が困ります。アクセシビリティの観点から、拡大を許可することが望ましいです。"}, {"t": "viewportの記述", "q": "スマートフォンの画面の幅に合わせて表示し、最初の拡大率を1倍にするための、meta要素を記述しなさい。", "code": "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">", "e": "name を viewport にし、content に width=device-width と initial-scale=1 を指定します。initial-scale=1.0 でも正解です。", "m": 3}, {"t": "picture要素の記述", "q": "画面の幅が768px以上のときは large.jpg を、それ以外のときは small.jpg を表示する、picture要素を記述しなさい。代替テキストは「風景」とすること。", "code": "<picture>\n  <source media=\"(min-width: 768px)\" srcset=\"large.jpg\">\n  <img src=\"small.jpg\" alt=\"風景\">\n</picture>", "e": "source要素の media属性に、条件を書き、srcset に画像を指定します。最後の img要素が、どの条件にも合わないときの画像で、alt もここに書きます。", "m": 3}], "ut": true, "lvn": "公式の出題範囲 1.4(レベル1 Ver2.5)"},
{"id": "l1e", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "APIの基礎知識(メディア・デバイス・ストレージ・通信)(1/3)", "dm": 1.5, "ps": [{"t": "CanvasとSVG", "q": "Canvas と SVG の説明として、適切なものはどれか。", "c": ["Canvasはベクター形式で、SVGはビットマップ形式である", "どちらも、写真を保存するためのファイル形式である", "どちらも、サーバ側でしか使えない", "Canvasはピクセル(ビットマップ)をJavaScriptで描き、SVGはXMLで書くベクター形式で、拡大しても粗くならない"], "k": 3, "e": "Canvasは、JavaScriptでピクセルを描くビットマップ方式です。SVGは、図形をXMLで記述するベクター方式で、拡大しても画質が落ちません。"}, {"t": "Canvasのコンテキスト", "q": "canvas要素に2Dの図形を描くために、描画コンテキストを取得するメソッドの呼び出し方はどれか。", "c": ["canvas.getContext(\"2d\")", "canvas.createContext(\"2d\")", "canvas.draw(\"2d\")", "canvas.getCanvas(\"2d\")"], "k": 0, "e": "getContext(\"2d\") で2Dの描画コンテキストを取得し、fillRect などのメソッドで描きます。"}, {"t": "Encrypted Media Extensions", "q": "Encrypted Media Extensions(EME)の説明として、適切なものはどれか。", "c": ["動画のファイルを圧縮するための形式", "ブラウザ間で、ビデオ通話をするためのAPI", "DRM(デジタル著作権管理)で保護された、暗号化された動画や音声を、ブラウザで再生するためのAPI", "動画に字幕を付けるためのファイル形式"], "k": 2, "e": "EMEは、暗号化されたメディアをブラウザで再生するための仕組みです。ビデオ通話はWebRTC、字幕のファイル形式はWebVTTです。"}, {"t": "アダプティブストリーミング", "q": "HLS や MPEG-DASH の説明として、適切なものはどれか。", "c": ["音声だけを配信するための専用の回線", "画像を圧縮するファイル形式", "動画をダウンロードしてから、まとめて再生する方式", "動画を細かく分けてHTTPで配信し、回線の速さに合わせて画質を切り替えられるストリーミングの方式"], "k": 3, "e": "HLS と MPEG-DASH は、HTTPを使ったアダプティブ(適応型)ストリーミングの方式です。ブラウザでは、Media Source Extensions(MSE)を使って再生できます。"}, {"t": "Geolocation API", "q": "Geolocation APIで、現在の位置を1回だけ取得するメソッドはどれか。", "c": ["navigator.geolocation.getAddress()", "window.location.getPosition()", "navigator.geolocation.watchPosition()", "navigator.geolocation.getCurrentPosition()"], "k": 3, "e": "getCurrentPosition は、現在位置を1回取得します。watchPosition は、位置が変わるたびに続けて取得します。位置情報の取得には、利用者の許可が必要です。"}, {"t": "Pointer Events", "q": "Pointer Events の説明として、適切なものはどれか。", "c": ["キーボードの入力だけを扱う", "マウス・タッチ・ペンなどの入力を、まとめて同じ形のイベントで扱える", "端末の傾きを取得できる", "位置情報を取得できる"], "k": 1, "e": "Pointer Events は、さまざまな入力機器を pointerdown や pointermove などのイベントでまとめて扱います。端末の傾きは DeviceOrientation Event で取得します。"}, {"t": "DeviceOrientation Event", "q": "端末の向き(傾き)が変わったことを取得するときに使うものはどれか。", "c": ["DeviceOrientation Event", "Server-Sent Events", "Touch Events", "Web Storage"], "k": 0, "e": "DeviceOrientation Event(deviceorientation イベント)で、端末の傾きの角度を取得できます。Touch Events はタッチ操作、Web Storage はデータの保存、Server-Sent Events はサーバからの通知です。"}, {"t": "localStorageとsessionStorage", "q": "Web Storage の localStorage と sessionStorage の違いとして、適切なものはどれか。", "c": ["localStorage のデータはタブを閉じると消えるが、sessionStorage のデータは残る", "どちらも、サーバに自動で送られる", "どちらも、データはサーバに保存される", "sessionStorage のデータはタブ(ウィンドウ)を閉じると消えるが、localStorage のデータはブラウザを閉じても残る"], "k": 3, "e": "sessionStorage は、そのタブ(ページのセッション)の間だけ残ります。localStorage は、削除するまで残ります。Cookieと違い、リクエストのたびにサーバへ送られることはありません。"}, {"t": "localStorageの記述", "q": "localStorage に、キー \"name\"、値 \"Hanako\" のデータを保存するJavaScriptを記述しなさい。", "code": "localStorage.setItem(\"name\", \"Hanako\");", "e": "setItem(キー, 値) で保存し、getItem(キー) で読み出し、removeItem(キー) で削除します。localStorage.name = \"Hanako\"; と書いても保存できます。", "m": 3}, {"t": "Indexed Database API", "q": "Indexed Database API(IndexedDB)の説明として、適切なものはどれか。", "c": ["データを、キーと文字列の組だけで少しだけ保存する仕組み", "ブラウザの中に、大量の構造化されたデータを保存し、キーやインデックスで検索できるデータベース", "サーバにあるデータベースに、SQLで接続する仕組み", "データを、ほかのブラウザと共有する仕組み"], "k": 1, "e": "IndexedDBは、ブラウザの中のデータベースで、オブジェクトをそのまま保存でき、インデックスで検索できます。キーと文字列の組で手軽に保存するのは Web Storage です。"}, {"t": "Web Workers", "q": "Web Workers の説明として、適切なものはどれか。", "c": ["通信をすべて暗号化する", "ページのDOMを、別のスレッドから直接書き換える", "サーバ側でJavaScriptを実行する", "重い処理を、画面の処理(メインスレッド)とは別のスレッドで実行し、画面が固まるのを防ぐ"], "k": 3, "e": "Web Workers は、バックグラウンドのスレッドでスクリプトを動かします。ワーカーからはDOMを直接操作できないので、postMessage でメインスレッドとデータをやり取りします。"}, {"t": "Service Workers", "q": "Service Workers でできることとして、適切なものはどれか。", "c": ["ネットワークのリクエストを仲介して、キャッシュを使い、オフラインでもページを表示する", "ページのDOMを直接書き換える", "ブラウザを閉じたあとで、PCの電源を切る", "HTTPのページでも、制限なくすべての機能が使える"], "k": 0, "e": "Service Workers は、ページとネットワークの間に入って、リクエストに応答します。キャッシュによるオフライン対応や、Push APIによるプッシュ通知に使います。安全のため、HTTPS のページでしか使えません(開発用の localhost は例外で、HTTP でも使えます)。DOMは直接操作できません。"}, {"t": "WebSocket", "q": "WebSocket API の説明として、適切なものはどれか。", "c": ["1つの接続を保ったまま、サーバとブラウザが双方向にリアルタイムでデータを送り合える", "ブラウザ同士が、サーバを通さずに映像を送り合う", "ページを読み込むたびに、新しい接続を作ってすぐ閉じる", "サーバからブラウザへの一方向の通知だけができる"], "k": 0, "e": "WebSocketは、ws:// や wss://(暗号化)で接続し、双方向に通信します。サーバからの一方向の通知は Server-Sent Events、ブラウザ同士の映像のやり取りは WebRTC です。"}, {"t": "Server-Sent Events", "q": "Server-Sent Events で、サーバからの通知を受け取るためにブラウザで使うオブジェクトはどれか。", "c": ["EventSource", "XMLHttpRequest", "WebSocket", "Worker"], "k": 0, "e": "Server-Sent Events は、new EventSource(URL) で接続し、サーバから一方向に送られるメッセージを受け取ります。"}, {"t": "WebRTC", "q": "WebRTC の説明として、適切なものはどれか。", "c": ["サーバのファイルを、ブラウザに保存する", "動画のファイル形式の1つである", "ブラウザ同士で、音声・映像・データを、リアルタイムに直接やり取りできる", "ブラウザの位置情報を取得する"], "k": 2, "e": "WebRTCは、ビデオ通話などに使われる、ブラウザ間(P2P)のリアルタイム通信の仕組みです。"}, {"t": "fetch API", "q": "fetch API について、適切なものはどれか。", "c": ["fetch() は、同期的に処理し、結果が返るまで画面が止まる", "fetch() は、サーバへのデータの送信にしか使えない", "fetch() は Promise を返し、then や await でレスポンスを受け取る", "fetch() は、WebSocketの接続を作る"], "k": 2, "e": "fetch() は Promise を返す非同期のAPIです。GETで取得することも、POSTで送信することもできます。XMLHttpRequest より簡潔に書けます。"}, {"t": "Canvasの描画", "q": "canvas要素のコンテキスト ctx で、「ctx.fillRect(10, 20, 100, 50)」を実行したときの説明として、適切なものはどれか。", "c": ["中心が(10, 20)で、半径100の円を描く", "左上が(100, 50)で、幅10、高さ20の長方形を描く", "(10, 20)から(100, 50)まで、線を引く", "左上が(10, 20)で、幅100、高さ50の長方形を塗りつぶして描く"], "k": 3, "e": "fillRect(x, y, 幅, 高さ) は、塗りつぶした長方形を描きます。線の長方形は strokeRect、円や円弧は arc です。"}, {"t": "Canvasのarc", "q": "canvasで、円や円弧を描くメソッドはどれか。", "c": ["oval", "round", "circle", "arc"], "k": 3, "e": "arc(x, y, 半径, 開始角, 終了角) で、円弧を描きます。円全体は、終了角を 2π(Math.PI * 2)にします。"}, {"t": "Canvasの大きさ", "q": "canvas要素の描画領域の大きさを正しく指定する方法として、適切なものはどれか。", "c": ["size属性で指定する", "width属性と height属性で指定する", "ctx.size で指定する", "CSSの width と height だけで指定する"], "k": 1, "e": "描画領域の大きさは、width、height属性で決まります。CSSだけで大きさを変えると、描画した内容が拡大・縮小されて、ぼやけることがあります。"}, {"t": "SVGの図形", "q": "SVGで、円を描く要素と、中心の位置・半径を表す属性の組合せはどれか。", "c": ["circle要素と、x、y、radius", "arc要素と、x、y、r", "circle要素と、cx、cy、r", "round要素と、cx、cy、r"], "k": 2, "e": "circle要素に、中心の座標 cx、cy と、半径 r を指定します。長方形は rect要素(x、y、width、height)です。"}, {"t": "SVGのviewBox", "q": "svg要素の viewBox属性の説明として、適切なものはどれか。", "c": ["svg要素の、枠線の太さ", "SVGの図形が描かれる座標系の範囲を指定し、表示の大きさに合わせて拡大・縮小される基準になる", "SVGを、表示するかどうか", "svg要素の、外側の余白"], "k": 1, "e": "viewBox=\"0 0 100 100\" のように、座標系の範囲を指定します。width と height が変わっても、図形は、この範囲を基準に拡大縮小されます。"}, {"t": "CanvasとSVGの違い", "q": "CanvasとSVGの違いとして、適切なものはどれか。", "c": ["Canvasの図形は、DOMの要素で、SVGの図形はピクセルの集まりである", "SVGの図形は、DOMの要素なので、CSSやイベントで操作できるが、Canvasに描いた図形は、ピクセルの集まりで、図形ごとの操作はできない", "どちらも、拡大してもぼやけない", "SVGは、JavaScriptを使わないと描けない"], "k": 1, "e": "SVGは、図形が要素として残るので、個別にスタイルやイベントを設定できます。Canvasは、描いたあとはピクセルなので、図形ごとの操作ができません。"}], "ut": true, "lvn": "公式の出題範囲 1.5(レベル1 Ver2.5)"},
{"id": "l1e2", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "APIの基礎知識(メディア・デバイス・ストレージ・通信)(2/3)", "dm": 1.5, "ps": [{"t": "Media Source Extensions", "q": "Media Source Extensions(MSE)の説明として、適切なものはどれか。", "c": ["動画を、暗号化して配信するAPI", "ブラウザ同士で、映像を直接やり取りするAPI", "JavaScriptで、メディアのデータを分割して組み立て、video要素やaudio要素に渡して再生できるようにするAPI", "動画から、字幕を自動で作るAPI"], "k": 2, "e": "MSEは、アダプティブストリーミング(HLSやMPEG-DASHなど)を、スクリプトで再生するために使われます。暗号化メディアの再生は、Encrypted Media Extensionsです。"}, {"t": "プレイリスト", "q": "HLSで使われるプレイリストファイルの拡張子はどれか。", "c": [".vtt", ".m3u8", ".mpd", ".json"], "k": 1, "e": "HLSのプレイリストは .m3u8 です。MPEG-DASHのマニフェストは .mpd、WebVTTは .vtt です。"}, {"t": "MPEG-DASH", "q": "MPEG-DASHのマニフェストファイル(MPD)の拡張子はどれか。", "c": [".dash", ".m3u8", ".mp4", ".mpd"], "k": 3, "e": "MPEG-DASHのマニフェストは .mpd です。HLSは .m3u8 です。"}, {"t": "play()", "q": "video要素のオブジェクト video で、スクリプトから再生を始めるメソッドはどれか。", "c": ["video.start()", "video.run()", "video.play()", "video.begin()"], "k": 2, "e": "play() で再生し、pause() で一時停止します。play() は Promise を返します。"}, {"t": "currentTime", "q": "video要素のオブジェクトで、現在の再生位置(秒)を、取得・設定できるプロパティはどれか。", "c": ["time", "currentTime", "seek", "position"], "k": 1, "e": "currentTime は、現在の再生位置(秒)です。duration は、メディア全体の長さ(秒)です。"}, {"t": "endedイベント", "q": "video要素で、再生が最後まで終わったときに発生するイベントはどれか。", "c": ["ended", "complete", "finish", "stop"], "k": 0, "e": "ended イベントは、再生が終わったときに発生します。timeupdate は、再生位置が変わるたびに発生します。"}, {"t": "Geolocationの座標", "q": "Geolocation APIで、位置情報(position)から、緯度を取り出すプロパティはどれか。", "c": ["position.coords.latitude", "position.coords.lat", "position.latitude", "position.lat"], "k": 0, "e": "座標は position.coords に入っていて、latitude が緯度、longitude が経度、accuracy が誤差(メートル)です。"}, {"t": "watchPosition", "q": "Geolocation APIで、位置が変わるたびに、位置情報を受け取り続けるメソッドはどれか。", "c": ["trackPosition", "getCurrentPosition", "listenPosition", "watchPosition"], "k": 3, "e": "watchPosition は、位置の変化を監視します。戻り値の ID を、clearWatch に渡すと、監視を止められます。getCurrentPosition は、1回だけ取得します。"}, {"t": "位置情報の許可", "q": "Geolocation APIの利用について、適切なものはどれか。", "c": ["HTTPのページでも、制限なく使える", "サーバ側でしか使えない", "HTTPSなどの安全なコンテキストでのみ使え、利用者の許可が必要である", "利用者の許可なしに、位置情報を取得できる"], "k": 2, "e": "位置情報は、個人情報なので、利用者の許可が必要です。また、安全なコンテキスト(HTTPSなど)でしか使えません。"}, {"t": "deviceorientationのbeta", "q": "deviceorientation イベントで、端末の前後の傾き(x軸まわりの回転)を表すプロパティはどれか。", "c": ["gamma", "theta", "beta", "alpha"], "k": 2, "e": "alpha は、z軸まわりの回転(端末の向き、方位)、beta は、前後の傾き、gamma は、左右の傾きです。"}, {"t": "devicemotion", "q": "devicemotion イベントで取得できる情報として、適切なものはどれか。", "c": ["端末のバッテリー残量", "端末の位置(緯度と経度)", "端末の加速度や、回転の速さ", "端末の画面の明るさ"], "k": 2, "e": "devicemotion は、加速度(acceleration)や、回転の速さ(rotationRate)を取得できます。位置は、Geolocation API です。"}, {"t": "Generic Sensor API", "q": "Generic Sensor APIで扱う、ジャイロスコープが測定するものとして、適切なものはどれか。", "c": ["端末の回転の速さ(角速度)", "端末の周りの明るさ", "端末の、移動の速さ", "端末の位置"], "k": 0, "e": "ジャイロスコープは、角速度(回転の速さ)を測ります。加速度センサー(Accelerometer)は、加速度を測ります。"}, {"t": "Touch Events", "q": "画面に指が触れたときに発生する、Touch Eventsのイベントはどれか。", "c": ["touchon", "touchbegin", "touchdown", "touchstart"], "k": 3, "e": "touchstart は触れたとき、touchmove は動かしたとき、touchend は離したとき、touchcancel は、中断されたときです。"}, {"t": "Pointer Eventsのイベント", "q": "Pointer Eventsで、ポインタ(マウスの矢印や、指やペンの接点)が押されたときに発生するイベントはどれか。", "c": ["pointerclick", "pointerpress", "pointeron", "pointerdown"], "k": 3, "e": "pointerdown、pointermove、pointerup などがあります。pointerType で、入力機器(mouse、pen、touch)を区別できます。"}, {"t": "イベントの伝播", "q": "DOMのイベントで、イベントの伝播を止めるメソッドはどれか。", "c": ["preventDefault()", "haltPropagation()", "stopPropagation()", "stopEvent()"], "k": 2, "e": "stopPropagation() は、親要素などへの伝播を止めます。preventDefault() は、リンクの移動やフォームの送信などの、既定の動作を止めます。"}, {"t": "キーイベント", "q": "キーボードのキーが押されたときに発生するイベントはどれか。", "c": ["keyon", "keypush", "keydown", "keyset"], "k": 2, "e": "keydown は押したとき、keyup は離したときです。"}, {"t": "Web Storageの値", "q": "Web Storage(localStorage)に保存できる値の型として、適切なものはどれか。", "c": ["オブジェクトも、そのまま保存できる", "すべての型を、そのまま保存できる", "文字列", "数値と文字列だけ"], "k": 2, "e": "Web Storageの値は、文字列として保存されます。オブジェクトを保存するときは、JSON.stringify で文字列に変換します。"}, {"t": "storageイベント", "q": "Web Storageの storage イベントが発生するのは、どんなときか。", "c": ["同じタブで、ストレージを変更したとき", "ページを、読み込んだとき", "ブラウザを、起動したとき", "同じオリジンの別のタブやウィンドウで、ストレージが変更されたとき"], "k": 3, "e": "storage イベントは、変更したページ以外(同じオリジンの別のページ)で発生します。"}, {"t": "同一オリジン", "q": "Web Storageのデータが、共有される範囲として、適切なものはどれか。", "c": ["同じ端末のすべてのブラウザ", "同じドメインのすべてのサブドメイン", "同じブラウザで開いた、すべてのページ", "同じオリジン(スキーム、ホスト、ポートの組)のページ"], "k": 3, "e": "Web Storageは、オリジンごとに分かれています。http と https、ポートが違うと、別のオリジンです。"}, {"t": "IndexedDBの特徴", "q": "Indexed Database API(IndexedDB)の特徴として、適切なものはどれか。", "c": ["非同期のAPIで、大量のデータを、オブジェクトストアに保存できる", "データは、サーバに保存される", "同期のAPIで、データはSQLで操作する", "保存できるデータは、文字列だけである"], "k": 0, "e": "IndexedDBは、非同期のAPIで、リクエストの成功や失敗を、イベントで受け取ります。オブジェクトをそのまま保存でき、インデックスで検索できます。"}, {"t": "Workerとメッセージ", "q": "Web Workersで、メインのスクリプトからワーカーにデータを送るメソッドはどれか。", "c": ["worker.write()", "worker.postMessage()", "worker.emit()", "worker.send()"], "k": 1, "e": "postMessage で送り、onmessage で受け取ります。ワーカーからメインに送るときも、postMessage を使います。"}, {"t": "Workerの制限", "q": "Web Workersの中のスクリプトでできないこととして、適切なものはどれか。", "c": ["postMessage で、メッセージを送ること", "DOMを、直接操作すること", "計算を、行うこと", "importScripts で、別のスクリプトを読み込むこと"], "k": 1, "e": "ワーカーは、DOMやwindowオブジェクトにアクセスできません。結果を、メインのスクリプトに送って、メイン側で画面を更新します。"}], "ut": true, "lvn": "公式の出題範囲 1.5(レベル1 Ver2.5)"},
{"id": "l1e3", "group": "レベル1", "lv": "Lv1", "lvc": "l1", "name": "APIの基礎知識(メディア・デバイス・ストレージ・通信)(3/3)", "dm": 1.5, "ps": [{"t": "Service Workerの登録", "q": "Service Workerを、ページから登録するメソッドはどれか。", "c": ["document.serviceWorker.add()", "navigator.serviceWorker.register()", "window.registerWorker()", "navigator.serviceWorker.install()"], "k": 1, "e": "navigator.serviceWorker.register('/sw.js') で登録します。"}, {"t": "fetchイベント", "q": "Service Workerの fetch イベントの説明として、適切なものはどれか。", "c": ["Service Workerを、サーバからダウンロードしたときに発生する", "データベースの書き込みが、終わったときに発生する", "ページからのネットワークリクエストを横取りして、キャッシュなどから応答を返せる", "ページを、閉じたときに発生する"], "k": 2, "e": "fetch イベントの中で、respondWith() を使って、応答を返せます。これで、オフラインでもページを表示できます。"}, {"t": "installイベント", "q": "Service Workerの install イベントで、よく行われる処理として、適切なものはどれか。", "c": ["オフラインで使うファイルを、Cache APIで、あらかじめキャッシュに保存する", "利用者に、プッシュ通知を表示する", "サーバに、ログインする", "ページの、DOMを書き換える"], "k": 0, "e": "install イベントは、Service Workerがインストールされるとき(新しいバージョンのときも)に発生します。その中で、caches.open() などを使って、必要なファイルをキャッシュします。"}, {"t": "Push API", "q": "Push APIで、サーバからのプッシュ通知を受け取るために、必要になるものはどれか。", "c": ["Web Workers", "WebSocket", "Canvas", "Service Worker"], "k": 3, "e": "Push APIは、Service Workerで、メッセージを受け取ります。ページを開いていなくても、通知を受け取れます。利用者の許可が必要です。"}, {"t": "readyState", "q": "XMLHttpRequestで、通信が完了したことを表す readyState の値はどれか。", "c": ["1", "4", "2", "0"], "k": 1, "e": "readyState は、0(UNSENT)、1(OPENED)、2(HEADERS_RECEIVED)、3(LOADING)、4(DONE) です。"}, {"t": "CORS", "q": "ブラウザのJavaScriptが、別のオリジンのサーバにリクエストを送って、レスポンスを読み取るために、サーバが返す必要のあるヘッダはどれか。", "c": ["Set-Cookie", "Access-Control-Allow-Origin", "Cache-Control", "Content-Security"], "k": 1, "e": "CORS(オリジン間リソース共有)で、サーバが Access-Control-Allow-Origin ヘッダで、許可するオリジンを示します。ブラウザは、同一オリジンポリシーのため、許可されていない別オリジンのレスポンスを、スクリプトに渡しません。"}, {"t": "fetchとHTTPエラー", "q": "fetch()で、サーバが404のステータスコードを返したとき、Promiseの結果として、適切なものはどれか。", "c": ["成功として解決(resolve)され、レスポンスの ok プロパティが false になる", "例外が発生して、スクリプトが停止する", "Promiseは、いつまでも解決されない", "拒否(reject)される"], "k": 0, "e": "fetch()が拒否されるのは、ネットワークエラーなどのときだけです。404や500でも、通信は成功しているので、解決されます。response.ok や status で確認します。"}, {"t": "fetchでPOST", "q": "fetch()で、フォームのデータをPOSTで送るために、第2引数に指定するオプションとして、適切なものはどれか。", "c": ["{ send: \"POST\", content: データ }", "{ post: データ }", "{ method: \"POST\", body: データ }", "{ type: \"POST\", data: データ }"], "k": 2, "e": "fetch(URL, { method: \"POST\", body: ... }) のように、method と body を指定します。"}, {"t": "WebSocketのハンドシェイク", "q": "WebSocketの接続を始めるときの手順として、適切なものはどれか。", "c": ["最初にHTTPのリクエスト(Upgradeヘッダ付き)を送り、サーバが101で応答して、WebSocketに切り替える", "UDPで、接続を確立する", "FTPで、接続を確立する", "最初から、HTTPとは別の専用ポートで、直接接続する"], "k": 0, "e": "WebSocketは、HTTPのアップグレード要求で始まり、サーバが 101 Switching Protocols で応答すると、双方向の通信に切り替わります。"}, {"t": "wss", "q": "WebSocketで、通信を暗号化して接続するときに使う、URLのスキームはどれか。", "c": ["ws://", "wss://", "sslws://", "wsecure://"], "k": 1, "e": "ws:// は暗号化なし、wss:// はTLSで暗号化されます。HTTPSのページから接続するときは、wss:// を使います。"}, {"t": "WebSocketのイベント", "q": "WebSocketで、サーバからメッセージを受け取ったときに発生するイベントはどれか。", "c": ["message", "receive", "data", "read"], "k": 0, "e": "onmessage(または message イベント)でメッセージを受け取り、send() で送ります。接続したときは open、閉じたときは close が発生します。"}, {"t": "text/event-stream", "q": "Server-Sent Eventsで、サーバが返すレスポンスの Content-Type はどれか。", "c": ["multipart/form-data", "application/json", "text/html", "text/event-stream"], "k": 3, "e": "サーバは、text/event-stream で、メッセージを送り続けます。EventSource は、接続が切れると、自動で再接続を試みます。"}, {"t": "SSEとWebSocket", "q": "Server-Sent Eventsと、WebSocketの違いとして、適切なものはどれか。", "c": ["Server-Sent Eventsは、双方向の通信で、WebSocketは、一方向の通信である", "どちらも、ブラウザ同士の直接通信である", "どちらも、一方向の通信である", "Server-Sent Eventsは、サーバからブラウザへの、一方向の通信で、WebSocketは、双方向の通信である"], "k": 3, "e": "Server-Sent Eventsは、サーバからの通知に向いています。ブラウザからサーバへ送るデータは、別にfetchなどで送ります。"}, {"t": "getUserMedia", "q": "WebRTCで、カメラやマイクから、映像や音声を取得するメソッドはどれか。", "c": ["document.getCamera()", "navigator.mediaDevices.getUserMedia()", "window.capture()", "navigator.camera.open()"], "k": 1, "e": "getUserMedia() で、カメラとマイクにアクセスします。利用者の許可が必要です。"}, {"t": "STUN", "q": "WebRTCで使われる、STUNサーバの役割として、適切なものはどれか。", "c": ["NATの内側にある端末が、外から見たときのアドレス(グローバルIPアドレスとポート)を知る手助けをする", "利用者を、認証する", "映像や音声を、圧縮する", "映像や音声を、すべて中継する"], "k": 0, "e": "STUNは、自分の外から見たアドレスを教えます。直接の通信ができないときに、データを中継するのは、TURNサーバです。"}, {"t": "RTCDataChannel", "q": "WebRTCの RTCDataChannel の説明として、適切なものはどれか。", "c": ["サーバのデータを、取得する", "データベースに、接続する", "映像や音声以外の、任意のデータを、ブラウザ同士で直接送り合う", "ファイルを、サーバにアップロードする"], "k": 2, "e": "RTCDataChannelは、テキストやバイナリを、ブラウザ間で、直接送受信します。"}, {"t": "イベントの記述", "q": "id が send のボタンを、クリックしたとき、id が name の入力欄の値を、コンソールに出力する(console.log)、JavaScriptを、addEventListener を使って記述しなさい。", "code": "document.getElementById(\"send\").addEventListener(\"click\", function () {\n  console.log(document.getElementById(\"name\").value);\n});", "e": "getElementById で要素を取り、addEventListener に \"click\" と関数を渡します。入力欄の値は value で取得します。アロー関数や querySelector を使う書き方でも正解です。", "m": 3}, {"t": "fetchの記述", "q": "fetch()で、/api/items のJSONを取得し、その内容を、console.log で出力する、JavaScriptを、then を使って記述しなさい。", "code": "fetch(\"/api/items\")\n  .then(function (res) { return res.json(); })\n  .then(function (data) { console.log(data); });", "e": "res.json() も Promise を返すので、then をつなげます。アロー関数でも、async と await を使った書き方でも正解です。", "m": 3}, {"t": "WebSocketの記述", "q": "wss://example.com/chat に接続し、メッセージを受け取ったら、その内容(event.data)を、console.log で出力するJavaScriptを記述しなさい。", "code": "var ws = new WebSocket(\"wss://example.com/chat\");\nws.onmessage = function (event) {\n  console.log(event.data);\n};", "e": "new WebSocket(URL) で接続し、onmessage(または addEventListener(\"message\", ...))でメッセージを受け取ります。メッセージの内容は、event.data です。", "m": 3}, {"t": "Canvasの記述", "q": "id が c の canvas要素から、2Dコンテキストを取得し、色を赤(red)にして、左上が(0, 0)で、幅50、高さ30の長方形を塗りつぶして描く、JavaScriptを記述しなさい。", "code": "var ctx = document.getElementById(\"c\").getContext(\"2d\");\nctx.fillStyle = \"red\";\nctx.fillRect(0, 0, 50, 30);", "e": "getContext(\"2d\") でコンテキストを取得し、fillStyle で色を指定してから、fillRect で描きます。fillStyle は、fillRect の前に指定します。", "m": 3}], "ut": true, "lvn": "公式の出題範囲 1.5(レベル1 Ver2.5)"}
];
